(335507,37279,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il devrait demander à son pote de ... cette branche en fleurs, sérieux.'::text,'pousser'::text,'pousser'::text,'poussant'::text,'Frérot, il devrait demander à son pote de pousser cette branche en fleurs, sérieux.'::text),
