(335541,37283,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ihrer Schönheit bringen die Blüten das Subjekt offenbar zum Niesen.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz ihrer Schönheit bringen die Blüten das Subjekt offenbar zum Niesen.'::text),
(335545,37283,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... свою красу, цвіт, вочевидь, змушує суб''єкта чхати.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри свою красу, цвіт, вочевидь, змушує суб''єкта чхати.'::text),
