(335546,37283,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güzelliğine ..., çiçekler belli ki deneği hapşırtıyor.'::text,'rağmen'::text,'karşın'::text,'yüzünden'::text,'Güzelliğine rağmen, çiçekler belli ki deneği hapşırtıyor.'::text),
