(389109,43235,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie den Dreck von ihren Handflächen ..., liefen dunkle Krümel ins Waschbecken.'::text,'schrubbte'::text,'abschrubbte'::text,'abgeschrubbt hat'::text,'Während sie den Dreck von ihren Handflächen schrubbte, liefen dunkle Krümel ins Waschbecken.'::text),
(389113,43235,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... бруд з долонь, темні крихти стікали в раковину.'::text,'відтирала'::text,'відтерла'::text,'відтерла'::text,'Поки вона відтирала бруд з долонь, темні крихти стікали в раковину.'::text),
(389112,43235,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... la suciedad de sus palmas, unas motas oscuras caían al lavabo.'::text,'frotaba'::text,'frotó'::text,'ha frotado'::text,'Mientras frotaba la suciedad de sus palmas, unas motas oscuras caían al lavabo.'::text),
