(389130,43237,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, bro, ... el jabón, se quitó la suciedad y sonrió, sin mentir.'::text,'agarró'::text,'estaba agarrando'::text,'agarra'::text,'Qué va, bro, agarró el jabón, se quitó la suciedad y sonrió, sin mentir.'::text),
(389129,43237,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frère, elle ... le savon, a frotté la saleté et a souri, sans mentir.'::text,'a attrapé'::text,'attrapait'::text,'attrape'::text,'Nan frère, elle a attrapé le savon, a frotté la saleté et a souri, sans mentir.'::text),
