(389133,43237,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, ... a szappant, lesikálta a koszt és mosolygott, komolyan.'::text,'felkapta'::text,'kapkodta'::text,'felkapja'::text,'Nem, tesó, felkapta a szappant, lesikálta a koszt és mosolygott, komolyan.'::text),
(389136,43238,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo Bro, sie ... sich jeden Krümel Dreck von den Händen gewaschen, ohne Witz.'::text,'hat'::text,'hat'::text,'wäscht'::text,'Yo Bro, sie hat sich jeden Krümel Dreck von den Händen gewaschen, ohne Witz.'::text),
(389140,43238,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, бро, вона ... з рук кожну крихту бруду, без брехні.'::text,'змила'::text,'змивала'::text,'змиває'::text,'Йо, бро, вона змила з рук кожну крихту бруду, без брехні.'::text),
(389139,43238,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, bro, ... hasta el último resto de suciedad de las manos, en serio.'::text,'se ha lavado'::text,'se ha estado lavando'::text,'se lava'::text,'Oye, bro, se ha lavado hasta el último resto de suciedad de las manos, en serio.'::text),
(389138,43238,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh frère, elle ... chaque trace de saleté de ses mains, sans mentir.'::text,'a lavé'::text,'est en train de laver'::text,'lave'::text,'Wesh frère, elle a lavé chaque trace de saleté de ses mains, sans mentir.'::text),
(389141,43238,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ellerindeki kirin her zerresini ..., yemin ederim.'::text,'yıkadı'::text,'yıkayıp duruyor'::text,'yıkar'::text,'Kanka, ellerindeki kirin her zerresini yıkadı, yemin ederim.'::text),
(389142,43238,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... a kezéről a kosz minden darabját, komolyan.'::text,'lemosta'::text,'mossa már egy ideje'::text,'mossa'::text,'Tesó, lemosta a kezéről a kosz minden darabját, komolyan.'::text),
(389145,43239,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis 9 Uhr ... sie den Schmutz vor dem Kundentermin von beiden Händen abgewaschen.'::text,'hatte'::text,'hat'::text,'wäscht'::text,'Bis 9 Uhr hatte sie den Schmutz vor dem Kundentermin von beiden Händen abgewaschen.'::text),
(389149,43239,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 9-ї ранку вона вже ... бруд з обох рук перед зустріччю з клієнтом.'::text,'змила'::text,'змила'::text,'змиває'::text,'До 9-ї ранку вона вже змила бруд з обох рук перед зустріччю з клієнтом.'::text),
(389148,43239,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A las 9 de la mañana ya ... la suciedad de ambas manos antes de la reunión con el cliente.'::text,'se había lavado'::text,'se ha lavado'::text,'se lava'::text,'A las 9 de la mañana ya se había lavado la suciedad de ambas manos antes de la reunión con el cliente.'::text),
(389147,43239,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À 9 h, elle ... la saleté de ses deux mains avant le rendez-vous client.'::text,'avait lavé'::text,'a lavé'::text,'lave'::text,'À 9 h, elle avait lavé la saleté de ses deux mains avant le rendez-vous client.'::text),
(389150,43239,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabah 9''a kadar müşteri toplantısından önce iki elindeki kiri de ...'::text,'yıkamıştı'::text,'yıkadı'::text,'yıkıyor'::text,'Sabah 9''a kadar müşteri toplantısından önce iki elindeki kiri de yıkamıştı.'::text),
(389151,43239,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reggel 9-re már ... a koszt mindkét kezéről az ügyféltalálkozó előtt.'::text,'lemosta'::text,'lemosta'::text,'lemossa'::text,'Reggel 9-re már lemosta a koszt mindkét kezéről az ügyféltalálkozó előtt.'::text),
(389154,43240,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie den Dreck abwäscht, ... ihre Hände sauber, weil Waschen genau das macht.'::text,'sind'::text,'wären'::text,'waren'::text,'Wenn sie den Dreck abwäscht, sind ihre Hände sauber, weil Waschen genau das macht.'::text),
(389158,43240,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона змиє бруд, її руки ... чистими, бо саме це й робить миття.'::text,'будуть'::text,'були б'::text,'були'::text,'Якщо вона змиє бруд, її руки будуть чистими, бо саме це й робить миття.'::text),
(389157,43240,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se lava la suciedad, sus manos ... limpias, porque eso es lo que hace lavarse.'::text,'estarán'::text,'estarían'::text,'estaban'::text,'Si se lava la suciedad, sus manos estarán limpias, porque eso es lo que hace lavarse.'::text),
(389156,43240,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle lave la saleté, ses mains ... propres, parce que c''est ce que fait le lavage.'::text,'seront'::text,'seraient'::text,'étaient'::text,'Si elle lave la saleté, ses mains seront propres, parce que c''est ce que fait le lavage.'::text),
(389159,43240,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kiri yıkarsa elleri temiz ..., çünkü yıkamak tam olarak bunu yapar.'::text,'olacak'::text,'olurdu'::text,'idi'::text,'Kiri yıkarsa elleri temiz olacak, çünkü yıkamak tam olarak bunu yapar.'::text),
(389160,43240,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha lemossa a koszt, a keze tiszta ..., mert a mosás pontosan ezt csinálja.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha lemossa a koszt, a keze tiszta lesz, mert a mosás pontosan ezt csinálja.'::text),
(389163,43241,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Schmutz keine Bakterien ..., wäre das Waschen typischerweise weniger wichtig.'::text,'enthielte'::text,'enthält'::text,'enthalten würde'::text,'Wenn der Schmutz keine Bakterien enthielte, wäre das Waschen typischerweise weniger wichtig.'::text),
(389167,43241,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби бруд ... бактерій, миття, як правило, було б менш важливим.'::text,'не містив'::text,'не містить'::text,'не містив би'::text,'Якби бруд не містив бактерій, миття, як правило, було б менш важливим.'::text),
(389166,43241,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la suciedad no ... bacterias, lavarse sería normalmente menos importante.'::text,'contuviera'::text,'contiene'::text,'contendría'::text,'Si la suciedad no contuviera bacterias, lavarse sería normalmente menos importante.'::text),
(389165,43241,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la saleté ne ... aucune bactérie, le lavage serait généralement moins important.'::text,'contenait'::text,'contient'::text,'contiendrait'::text,'Si la saleté ne contenait aucune bactérie, le lavage serait généralement moins important.'::text),
(389168,43241,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kir hiç bakteri ..., yıkamak genellikle daha az önemli olurdu.'::text,'içermeseydi'::text,'içermiyor'::text,'içermezdi'::text,'Kir hiç bakteri içermeseydi, yıkamak genellikle daha az önemli olurdu.'::text),
(389169,43241,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kosz nem ... baktériumokat, a mosás jellemzően kevésbé lenne fontos.'::text,'tartalmazna'::text,'tartalmaz'::text,'tartalmazna'::text,'Ha a kosz nem tartalmazna baktériumokat, a mosás jellemzően kevésbé lenne fontos.'::text),
(389172,43242,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Dreck ... mit lila Seife und warmem Wasser von ihren Händen abgewaschen.'::text,'wurde'::text,'wird'::text,'hat'::text,'Der Dreck wurde mit lila Seife und warmem Wasser von ihren Händen abgewaschen.'::text),
(389176,43242,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бруд ... з її рук фіолетовим милом і теплою водою.'::text,'був змитий'::text,'змивається'::text,'змив'::text,'Бруд був змитий з її рук фіолетовим милом і теплою водою.'::text),
(389175,43242,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La suciedad ... de sus manos con jabón morado y agua tibia.'::text,'fue lavada'::text,'es lavada'::text,'lavó'::text,'La suciedad fue lavada de sus manos con jabón morado y agua tibia.'::text),
(389174,43242,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La saleté ... de ses mains avec du savon violet et de l''eau tiède.'::text,'a été lavée'::text,'est lavée'::text,'a lavé'::text,'La saleté a été lavée de ses mains avec du savon violet et de l''eau tiède.'::text),
(389177,43242,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kir, mor sabun ve ılık suyla ellerinden ...'::text,'yıkandı'::text,'yıkanır'::text,'yıkadı'::text,'Kir, mor sabun ve ılık suyla ellerinden yıkandı.'::text),
(389178,43242,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kosz ... a kezéről lila szappannal és meleg vízzel.'::text,'le lett mosva'::text,'le van mosva'::text,'lemosta'::text,'A kosz le lett mosva a kezéről lila szappannal és meleg vízzel.'::text),
(389181,43243,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die lila Seife ... jeden Krümel Dreck von ihren Handflächen.'::text,'entfernte'::text,'wurde entfernt'::text,'entfernend'::text,'Die lila Seife entfernte jeden Krümel Dreck von ihren Handflächen.'::text),
(389185,43243,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фіолетове мило ... з її долонь кожну крихту бруду.'::text,'видалило'::text,'було видалене'::text,'видалення'::text,'Фіолетове мило видалило з її долонь кожну крихту бруду.'::text),
(389184,43243,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jabón morado ... toda la suciedad de sus palmas.'::text,'quitó'::text,'fue quitado'::text,'quitando'::text,'El jabón morado quitó toda la suciedad de sus palmas.'::text),
(389183,43243,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le savon violet ... chaque trace de saleté de ses paumes.'::text,'a enlevé'::text,'a été enlevé'::text,'enlevant'::text,'Le savon violet a enlevé chaque trace de saleté de ses paumes.'::text),
(389186,43243,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mor sabun avuçlarındaki kirin her zerresini ...'::text,'temizledi'::text,'temizlendi'::text,'temizleyen'::text,'Mor sabun avuçlarındaki kirin her zerresini temizledi.'::text),
(389187,43243,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lila szappan a kosz minden darabját ... a tenyeréről.'::text,'eltávolította'::text,'el lett távolítva'::text,'eltávolítva'::text,'A lila szappan a kosz minden darabját eltávolította a tenyeréről.'::text),
(389190,43244,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... eine Stunde lang an ihrer Fahrradkette herumgeschraubt, deshalb bedeckte Dreck ihre beiden Hände.'::text,'hatte'::text,'hat'::text,'schraubt'::text,'Sie hatte eine Stunde lang an ihrer Fahrradkette herumgeschraubt, deshalb bedeckte Dreck ihre beiden Hände.'::text),
(389194,43244,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... ланцюг велосипеда цілу годину, тож бруд укрив обидві її руки.'::text,'лагодила'::text,'лагодить'::text,'лагодить'::text,'Вона лагодила ланцюг велосипеда цілу годину, тож бруд укрив обидві її руки.'::text),
(389193,43244,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la cadena de la bici durante una hora, así que la suciedad le cubrió las dos manos.'::text,'Había estado arreglando'::text,'Ha estado arreglando'::text,'Está arreglando'::text,'Había estado arreglando la cadena de la bici durante una hora, así que la suciedad le cubrió las dos manos.'::text),
(389192,43244,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sa chaîne de vélo depuis une heure, si bien que la saleté recouvrait ses deux mains.'::text,'réparait'::text,'répare'::text,'répare'::text,'Elle réparait sa chaîne de vélo depuis une heure, si bien que la saleté recouvrait ses deux mains.'::text),
(389195,43244,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saattir bisiklet zincirini ..., bu yüzden iki eli de kir içinde kaldı.'::text,'tamir ediyordu'::text,'tamir ediyor'::text,'tamir ediyor'::text,'Bir saattir bisiklet zincirini tamir ediyordu, bu yüzden iki eli de kir içinde kaldı.'::text),
(389196,43244,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órája ... a biciklije láncát, így mindkét kezét kosz borította.'::text,'szerelte'::text,'szereli'::text,'szereli'::text,'Egy órája szerelte a biciklije láncát, így mindkét kezét kosz borította.'::text),
(389721,43303,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit werden ungefähr zwölf Personen das geräumige Sofa ...'::text,'besetzt halten'::text,'besetzen'::text,'besetzen'::text,'Morgen um diese Zeit werden ungefähr zwölf Personen das geräumige Sofa besetzt halten.'::text),
(389725,43303,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час приблизно дванадцять людей ... просторий диван.'::text,'займатимуть'::text,'займуть'::text,'займають'::text,'Завтра в цей час приблизно дванадцять людей займатимуть просторий диван.'::text),
(389724,43303,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, aproximadamente doce personas ... el espacioso sofá.'::text,'estarán ocupando'::text,'ocuparán'::text,'ocupan'::text,'Mañana a esta hora, aproximadamente doce personas estarán ocupando el espacioso sofá.'::text),
(389723,43303,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, environ douze personnes ... le canapé spacieux.'::text,'seront en train d''occuper'::text,'occuperont'::text,'occupent'::text,'Demain à la même heure, environ douze personnes seront en train d''occuper le canapé spacieux.'::text),
(389726,43303,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde yaklaşık on iki kişi geniş kanepeyi ...'::text,'işgal ediyor olacak'::text,'işgal edecek'::text,'işgal ediyor'::text,'Yarın bu saatlerde yaklaşık on iki kişi geniş kanepeyi işgal ediyor olacak.'::text),
(389727,43303,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor körülbelül tizenkét ember ... a tágas kanapét.'::text,'foglalja majd el'::text,'fogja elfoglalni'::text,'foglalja el'::text,'Holnap ilyenkor körülbelül tizenkét ember foglalja majd el a tágas kanapét.'::text),
(389730,43304,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Wohnzimmer so geräumig ist, ... immer Freunde herein und zerstören die Ruhe!'::text,'rennen'::text,'rannten'::text,'werden rennen'::text,'Wenn ein Wohnzimmer so geräumig ist, rennen immer Freunde herein und zerstören die Ruhe!'::text),
(389734,43304,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вітальня така простора, друзі завжди ... всередину й руйнують спокій!'::text,'вбігають'::text,'вбігли'::text,'вбіжать'::text,'Якщо вітальня така простора, друзі завжди вбігають всередину й руйнують спокій!'::text),
(389733,43304,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si un salón es así de espacioso, los amigos siempre ... y destrozan la paz!'::text,'entran corriendo'::text,'entraron corriendo'::text,'entrarán corriendo'::text,'¡Si un salón es así de espacioso, los amigos siempre entran corriendo y destrozan la paz!'::text),
(389732,43304,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un salon est aussi spacieux, les amis ... toujours et détruisent la paix !'::text,'déboulent'::text,'déboulèrent'::text,'débouleront'::text,'Si un salon est aussi spacieux, les amis déboulent toujours et détruisent la paix !'::text),
(389735,43304,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir oturma odası bu kadar genişse, arkadaşlar hep içeri ... ve huzuru mahveder!'::text,'dalar'::text,'daldı'::text,'dalacak'::text,'Bir oturma odası bu kadar genişse, arkadaşlar hep içeri dalar ve huzuru mahveder!'::text),
(389736,43304,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy nappali ilyen tágas, a barátok mindig ... és tönkreteszik a nyugalmat!'::text,'berontanak'::text,'berontottak'::text,'be fognak rontani'::text,'Ha egy nappali ilyen tágas, a barátok mindig berontanak és tönkreteszik a nyugalmat!'::text),
(389739,43305,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwölf Freunde und immer noch Platz! Dieses Sofa ... absolut geräumig sein!'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Zwölf Freunde und immer noch Platz! Dieses Sofa muss absolut geräumig sein!'::text),
(389743,43305,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дванадцять друзів, і ще є місце! Цей диван ... бути неймовірно просторим!'::text,'мусить'::text,'не може'::text,'мав би'::text,'Дванадцять друзів, і ще є місце! Цей диван мусить бути неймовірно просторим!'::text),
(389742,43305,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Doce amigos y todavía sobra sitio! ¡Este sofá ... ser enorme!'::text,'debe de'::text,'no puede'::text,'debería'::text,'¡Doce amigos y todavía sobra sitio! ¡Este sofá debe de ser enorme!'::text),
(389741,43305,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Douze amis et encore de la place ! Ce canapé ... être incroyablement spacieux !'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Douze amis et encore de la place ! Ce canapé doit être incroyablement spacieux !'::text),
(389744,43305,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On iki arkadaş ve hâlâ yer var! Bu kanepe kesinlikle çok geniş ...!'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'On iki arkadaş ve hâlâ yer var! Bu kanepe kesinlikle çok geniş olmalı!'::text),
(389745,43305,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tizenkét barát, és még mindig van hely! Ennek a kanapénak ... hihetetlenül tágasnak lennie!'::text,'kell'::text,'nem lehet'::text,'kellene'::text,'Tizenkét barát, és még mindig van hely! Ennek a kanapénak kell hihetetlenül tágasnak lennie!'::text),
(389757,43307,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, er hat mir erzählt, dass er sich in der Woche davor eine geräumige Wohnung ganz für sich allein ...'::text,'gekauft hatte'::text,'gekauft hat'::text,'kauft'::text,'Süße, er hat mir erzählt, dass er sich in der Woche davor eine geräumige Wohnung ganz für sich allein gekauft hatte.'::text),
(389761,43307,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що тижнем раніше ... простору квартиру тільки для себе.'::text,'купив'::text,'купив'::text,'купує'::text,'Подруго, він сказав мені, що тижнем раніше купив простору квартиру тільки для себе.'::text),
(389760,43307,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me contó que la semana anterior ... un piso espacioso solo para él.'::text,'se había comprado'::text,'se ha comprado'::text,'se compra'::text,'Tía, me contó que la semana anterior se había comprado un piso espacioso solo para él.'::text),
(389759,43307,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il ... un appartement spacieux rien que pour lui la semaine d''avant.'::text,'avait acheté'::text,'a acheté'::text,'achète'::text,'Meuf, il m''a dit qu''il avait acheté un appartement spacieux rien que pour lui la semaine d''avant.'::text),
(389762,43307,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana bir hafta önce sadece kendisi için geniş bir daire ... söyledi.'::text,'almış olduğunu'::text,'aldığını'::text,'aldığını'::text,'Kızım, bana bir hafta önce sadece kendisi için geniş bir daire almış olduğunu söyledi.'::text),
(389763,43307,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy az előző héten ... egy tágas lakást csak magának.'::text,'vett'::text,'vett'::text,'vesz'::text,'Csajszi, azt mondta, hogy az előző héten vett egy tágas lakást csak magának.'::text),
(389766,43308,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... allein in dieser geräumigen Wohnung.'::text,'lebte er früher'::text,'lebte er früher'::text,'war er gewohnt zu leben'::text,'Bestie, angeblich lebte er früher allein in dieser geräumigen Wohnung.'::text),
(389770,43308,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... сам у тій просторій квартирі.'::text,'раніше жив'::text,'бувало, жив'::text,'звик жити'::text,'Подруго, кажуть, він раніше жив сам у тій просторій квартирі.'::text),
(389769,43308,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ... solo en ese piso tan espacioso.'::text,'antes vivía'::text,'vivía'::text,'estaba acostumbrado a vivir'::text,'Amiga, al parecer antes vivía solo en ese piso tan espacioso.'::text),
(389768,43308,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma bestie, apparemment il ... seul dans cet appartement spacieux.'::text,'vivait avant'::text,'vivait'::text,'avait l''habitude de vivre'::text,'Ma bestie, apparemment il vivait avant seul dans cet appartement spacieux.'::text),
(389771,43308,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre o geniş dairede tek başına ...'::text,'yaşarmış'::text,'yaşarmış'::text,'yaşamaya alışkınmış'::text,'Kanka, duyduğuma göre o geniş dairede tek başına yaşarmış.'::text),
(389772,43308,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ... egyedül abban a tágas lakásban.'::text,'régen lakott'::text,'lakott'::text,'hozzá volt szokva, hogy lakjon'::text,'Csajszi, állítólag régen lakott egyedül abban a tágas lakásban.'::text),
(389775,43309,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er liebt es, sich allein auf dem geräumigen Sofa ...'::text,'auszustrecken'::text,'auszustrecken'::text,'ausstrecken'::text,'Er liebt es, sich allein auf dem geräumigen Sofa auszustrecken.'::text),
(389779,43309,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обожнює ... сам на просторому дивані.'::text,'розлягатися'::text,'розлягатися'::text,'розлягатися'::text,'Він обожнює розлягатися сам на просторому дивані.'::text),
(389778,43309,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le encanta ... solo en el espacioso sofá.'::text,'estirarse'::text,'estirarse'::text,'estirarse'::text,'Le encanta estirarse solo en el espacioso sofá.'::text),
(389777,43309,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il adore ... seul sur le canapé spacieux.'::text,'s''étaler'::text,'s''étaler'::text,'s''étaler'::text,'Il adore s''étaler seul sur le canapé spacieux.'::text),
(389780,43309,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geniş kanepede tek başına ... bayılıyor.'::text,'uzanmaya'::text,'uzanmaya'::text,'uzanmak'::text,'Geniş kanepede tek başına uzanmaya bayılıyor.'::text),
(389781,43309,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Imád egyedül ... a tágas kanapén.'::text,'elnyúlni'::text,'elnyúlni'::text,'elnyúlni'::text,'Imád egyedül elnyúlni a tágas kanapén.'::text),
(389784,43310,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Wohnzimmer ist echt geräumig, ...?'::text,'nicht wahr'::text,'oder'::text,'ja'::text,'Das Wohnzimmer ist echt geräumig, nicht wahr?'::text),
(389788,43310,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вітальня справді простора, ...?'::text,'правда'::text,'чи не так'::text,'так'::text,'Вітальня справді простора, правда?'::text),
(389787,43310,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El salón es realmente espacioso, ¿...?'::text,'verdad'::text,'no'::text,'sí'::text,'El salón es realmente espacioso, ¿verdad?'::text),
(389786,43310,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le salon est vraiment spacieux, ... ?'::text,'n''est-ce pas'::text,'non'::text,'oui'::text,'Le salon est vraiment spacieux, n''est-ce pas ?'::text),
(389789,43310,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oturma odası gerçekten çok geniş, ...?'::text,'değil mi'::text,'değil mi'::text,'öyle mi'::text,'Oturma odası gerçekten çok geniş, değil mi?'::text),
(389790,43310,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nappali tényleg tágas, ...?'::text,'ugye'::text,'nem'::text,'igen'::text,'A nappali tényleg tágas, ugye?'::text),
(389793,43311,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Sofa ist geräumig, und ...'::text,'das Zimmer auch'::text,'das Zimmer auch'::text,'das Zimmer auch nicht'::text,'Das Sofa ist geräumig, und das Zimmer auch.'::text),
(389797,43311,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Диван просторий, і ...'::text,'кімната теж'::text,'кімната теж'::text,'кімната теж ні'::text,'Диван просторий, і кімната теж.'::text),
(389796,43311,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sofá es espacioso, y ...'::text,'la habitación también'::text,'la habitación también'::text,'la habitación tampoco'::text,'El sofá es espacioso, y la habitación también.'::text),
(389795,43311,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le canapé est spacieux, et ...'::text,'la pièce aussi'::text,'la pièce aussi'::text,'la pièce non plus'::text,'Le canapé est spacieux, et la pièce aussi.'::text),
(389798,43311,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanepe geniş, ...'::text,'oda da öyle'::text,'oda da öyle'::text,'oda da değil'::text,'Kanepe geniş, oda da öyle.'::text),
(389799,43311,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kanapé tágas, és ...'::text,'a szoba is'::text,'a szoba is'::text,'a szoba sem'::text,'A kanapé tágas, és a szoba is.'::text),
(389802,43312,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit Beginn des Teammeetings ... das geräumige Sofa 12 Kolleginnen und Kollegen, und es ist immer noch Platz frei.'::text,'fasst'::text,'fasst'::text,'fasst gerade'::text,'Seit Beginn des Teammeetings fasst das geräumige Sofa 12 Kolleginnen und Kollegen, und es ist immer noch Platz frei.'::text),
(389806,43312,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відколи почалася командна нарада, просторий диван ... 12 колег, і ще є вільне місце.'::text,'вміщує'::text,'вміщує'::text,'вміщує зараз'::text,'Відколи почалася командна нарада, просторий диван вміщує 12 колег, і ще є вільне місце.'::text),
(389805,43312,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desde que empezó la reunión del equipo, el espacioso sofá ... a 12 compañeros y aún sobra sitio.'::text,'ha acogido'::text,'acoge'::text,'está acogiendo'::text,'Desde que empezó la reunión del equipo, el espacioso sofá ha acogido a 12 compañeros y aún sobra sitio.'::text),
(389804,43312,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depuis le début de la réunion d''équipe, le canapé spacieux ... 12 collègues, et il reste de la place.'::text,'accueille'::text,'accueille'::text,'est en train d''accueillir'::text,'Depuis le début de la réunion d''équipe, le canapé spacieux accueille 12 collègues, et il reste de la place.'::text),
(389807,43312,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip toplantısı başladığından beri geniş kanepe 12 meslektaşı ..., üstelik hâlâ yer var.'::text,'ağırlıyor'::text,'ağırlar'::text,'ağırlıyor'::text,'Ekip toplantısı başladığından beri geniş kanepe 12 meslektaşı ağırlıyor, üstelik hâlâ yer var.'::text),
(389808,43312,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapatmegbeszélés kezdete óta a tágas kanapé ... 12 kollégát, és még mindig marad hely.'::text,'befogad'::text,'befogad'::text,'éppen befogad'::text,'A csapatmegbeszélés kezdete óta a tágas kanapé befogad 12 kollégát, és még mindig marad hely.'::text),
(337467,37497,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jetzt schon seit einer Stunde auf dem Sofa. Sehr ruhig, ein echter Notfall.'::text,'liegen'::text,'liegen gerade'::text,'liegen'::text,'Sie liegen jetzt schon seit einer Stunde auf dem Sofa. Sehr ruhig, ein echter Notfall.'::text),
(337471,37497,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... на тому дивані вже годину. Дуже спокійно, справжня надзвичайна ситуація.'::text,'лежать'::text,'лежать'::text,'лежать'::text,'Вони лежать на тому дивані вже годину. Дуже спокійно, справжня надзвичайна ситуація.'::text),
(337470,37497,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... en ese sofá desde hace una hora. Muy tranquilos, una auténtica emergencia.'::text,'Están tumbados'::text,'Están tumbados'::text,'Se tumban'::text,'Están tumbados en ese sofá desde hace una hora. Muy tranquilos, una auténtica emergencia.'::text),
(337469,37497,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... sur ce canapé depuis une heure. Très calmes, une vraie urgence.'::text,'sont allongés'::text,'sont allongés'::text,'s''allongent'::text,'Ils sont allongés sur ce canapé depuis une heure. Très calmes, une vraie urgence.'::text),
(337472,37497,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saattir ... o kanepede. Çok sakin, tam bir acil durum.'::text,'yatıyorlar'::text,'yatıyorlar'::text,'yatarlar'::text,'Bir saattir yatıyorlar o kanepede. Çok sakin, tam bir acil durum.'::text),
(337473,37497,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már egy órája ... azon a kanapén. Nagyon nyugodt, igazi vészhelyzet.'::text,'fekszenek'::text,'fekszenek'::text,'fekszenek'::text,'Már egy órája fekszenek azon a kanapén. Nagyon nyugodt, igazi vészhelyzet.'::text),
(337476,37498,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ..., als ihre Freundin ihr eine Decke umlegte, und dann wurde sie ruhig.'::text,'weinte gerade'::text,'weinte'::text,'hat geweint'::text,'Sie weinte gerade, als ihre Freundin ihr eine Decke umlegte, und dann wurde sie ruhig.'::text),
(337480,37498,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ..., коли подруга накинула на неї ковдру, а потім заспокоїлася.'::text,'плакала'::text,'заплакала'::text,'заплакала'::text,'Вона плакала, коли подруга накинула на неї ковдру, а потім заспокоїлася.'::text),
(337479,37498,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cuando su amiga le puso una manta por encima, y luego se calmó.'::text,'Estaba llorando'::text,'Lloró'::text,'Ha llorado'::text,'Estaba llorando cuando su amiga le puso una manta por encima, y luego se calmó.'::text),
(337478,37498,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... quand son amie lui a mis une couverture sur les épaules, puis elle s''est calmée.'::text,'pleurait'::text,'a pleuré'::text,'a pleuré'::text,'Elle pleurait quand son amie lui a mis une couverture sur les épaules, puis elle s''est calmée.'::text),
(337481,37498,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşı üstüne bir battaniye örttüğünde ..., sonra sakinleşti.'::text,'ağlıyordu'::text,'ağladı'::text,'ağlamış'::text,'Arkadaşı üstüne bir battaniye örttüğünde ağlıyordu, sonra sakinleşti.'::text),
(337482,37498,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., amikor a barátnője takarót terített rá, aztán megnyugodott.'::text,'Sírt'::text,'Elsírta magát'::text,'Sírt már'::text,'Sírt, amikor a barátnője takarót terített rá, aztán megnyugodott.'::text),
(337485,37499,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Freunde ... sie seit zehn Minuten, und jetzt ist sie ruhig.'::text,'umarmen'::text,'haben umarmt'::text,'umarmen gerade'::text,'Ihre Freunde umarmen sie seit zehn Minuten, und jetzt ist sie ruhig.'::text),
(337489,37499,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Друзі ... її вже десять хвилин, і тепер вона спокійна.'::text,'обіймають'::text,'обійняли'::text,'обіймають'::text,'Друзі обіймають її вже десять хвилин, і тепер вона спокійна.'::text),
(337488,37499,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus amigos la ... desde hace diez minutos, y ahora está tranquila.'::text,'abrazan'::text,'han abrazado'::text,'están abrazando'::text,'Sus amigos la abrazan desde hace diez minutos, y ahora está tranquila.'::text),
(337487,37499,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses amis ... depuis dix minutes, et maintenant elle est calme.'::text,'la serrent dans leurs bras'::text,'l''ont serrée dans leurs bras'::text,'sont en train de la serrer dans leurs bras'::text,'Ses amis la serrent dans leurs bras depuis dix minutes, et maintenant elle est calme.'::text),
(337490,37499,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları on dakikadır ona ..., şimdi sakin.'::text,'sarılıyor'::text,'sarıldı'::text,'sarılıyor'::text,'Arkadaşları on dakikadır ona sarılıyor, şimdi sakin.'::text),
(337491,37499,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátai tíz perce ... őt, és most már nyugodt.'::text,'ölelgetik'::text,'megölelték'::text,'ölelik'::text,'A barátai tíz perce ölelgetik őt, és most már nyugodt.'::text),
(337494,37500,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sich die Gruppe aufs Sofa legte, ... sie schon ruhig geworden.'::text,'war'::text,'ist'::text,'wird'::text,'Als sich die Gruppe aufs Sofa legte, war sie schon ruhig geworden.'::text),
(337498,37500,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли компанія лягла на диван, вона вже ... спокійною.'::text,'стала'::text,'стала'::text,'стає'::text,'Коли компанія лягла на диван, вона вже стала спокійною.'::text),
(337497,37500,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el grupo se tumbó en el sofá, ella ya ... tranquila.'::text,'se había quedado'::text,'se ha quedado'::text,'se queda'::text,'Para cuando el grupo se tumbó en el sofá, ella ya se había quedado tranquila.'::text),
(337496,37500,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le groupe s''est allongé sur le canapé, elle ... calme.'::text,'était devenue'::text,'est devenue'::text,'devient'::text,'Quand le groupe s''est allongé sur le canapé, elle était devenue calme.'::text),
(337499,37500,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup kanepeye uzandığında o çoktan ...'::text,'sakinleşmişti'::text,'sakinleşti'::text,'sakinleşiyor'::text,'Grup kanepeye uzandığında o çoktan sakinleşmişti.'::text),
(337500,37500,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a társaság lefeküdt a kanapéra, ő már ...'::text,'megnyugodott'::text,'megnyugodott'::text,'megnyugszik'::text,'Mire a társaság lefeküdt a kanapéra, ő már megnyugodott.'::text),
(337503,37501,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn niemand eine Decke bringt, ... sie nicht ruhig, und die Nacht ist ruiniert!'::text,'wird'::text,'würde'::text,'wurde'::text,'Wenn niemand eine Decke bringt, wird sie nicht ruhig, und die Nacht ist ruiniert!'::text),
(337507,37501,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ніхто не принесе ковдру, вона ..., і ніч буде зіпсована!'::text,'не заспокоїться'::text,'не заспокоїлася б'::text,'не заспокоїлася'::text,'Якщо ніхто не принесе ковдру, вона не заспокоїться, і ніч буде зіпсована!'::text),
(337506,37501,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si nadie trae una manta, ... y la noche se arruinará!'::text,'no se calmará'::text,'no se calmaría'::text,'no se calmó'::text,'¡Si nadie trae una manta, no se calmará y la noche se arruinará!'::text),
(337505,37501,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si personne n''apporte de couverture, elle ... et la soirée sera gâchée !'::text,'ne se calmera pas'::text,'ne se calmerait pas'::text,'ne s''est pas calmée'::text,'Si personne n''apporte de couverture, elle ne se calmera pas et la soirée sera gâchée !'::text),
(337508,37501,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse battaniye getirmezse ... ve gece mahvolacak!'::text,'sakinleşmeyecek'::text,'sakinleşmezdi'::text,'sakinleşmedi'::text,'Kimse battaniye getirmezse sakinleşmeyecek ve gece mahvolacak!'::text),
(337509,37501,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha senki nem hoz takarót, ... és az éjszaka tönkremegy!'::text,'nem fog megnyugodni'::text,'nem nyugodna meg'::text,'nem nyugodott meg'::text,'Ha senki nem hoz takarót, nem fog megnyugodni és az éjszaka tönkremegy!'::text),
(337512,37502,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ihre Freunde nicht da wären, ... nie wieder zur Ruhe. Ein totaler Albtraum!'::text,'fände sie'::text,'wird sie finden'::text,'fand sie'::text,'Wenn ihre Freunde nicht da wären, fände sie nie wieder zur Ruhe. Ein totaler Albtraum!'::text),
(337516,37502,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби її друзів там не було, вона ... спокійною. Повний жах!'::text,'ніколи б більше не почувалася'::text,'ніколи більше не почуватиметься'::text,'ніколи більше не почувалася'::text,'Якби її друзів там не було, вона ніколи б більше не почувалася спокійною. Повний жах!'::text),
(337515,37502,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sus amigos no estuvieran allí, ... tranquila de nuevo. ¡Una auténtica pesadilla!'::text,'nunca se sentiría'::text,'nunca se sentirá'::text,'nunca se sintió'::text,'Si sus amigos no estuvieran allí, nunca se sentiría tranquila de nuevo. ¡Una auténtica pesadilla!'::text),
(337514,37502,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ses amis n''étaient pas là, elle ... calme. Un vrai cauchemar !'::text,'ne se sentirait plus jamais'::text,'ne se sentira plus jamais'::text,'ne s''est plus jamais sentie'::text,'Si ses amis n''étaient pas là, elle ne se sentirait plus jamais calme. Un vrai cauchemar !'::text),
(337517,37502,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları orada olmasaydı, kendini bir daha asla sakin ...! Tam bir kâbus!'::text,'hissetmezdi'::text,'hissetmeyecek'::text,'hissetmedi'::text,'Arkadaşları orada olmasaydı, kendini bir daha asla sakin hissetmezdi! Tam bir kâbus!'::text),
(337518,37502,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a barátai nem lennének ott, ... többé nyugodtnak. Totális rémálom!'::text,'soha nem érezné magát'::text,'soha nem fogja érezni magát'::text,'soha nem érezte magát'::text,'Ha a barátai nem lennének ott, soha nem érezné magát többé nyugodtnak. Totális rémálom!'::text),
(337521,37503,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte mal, angeblich ... sie in eine riesige Decke gewickelt, bis sie ruhig war.'::text,'wurde'::text,'hat'::text,'wird'::text,'Warte mal, angeblich wurde sie in eine riesige Decke gewickelt, bis sie ruhig war.'::text),
(337525,37503,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, кажуть, її ... у величезну ковдру, поки вона не заспокоїлася.'::text,'загорнули'::text,'загорнула'::text,'загортають'::text,'Стривай, кажуть, її загорнули у величезну ковдру, поки вона не заспокоїлася.'::text),
(337524,37503,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, al parecer ... en una manta enorme hasta que se calmó.'::text,'fue envuelta'::text,'envolvió'::text,'es envuelta'::text,'Espera, al parecer fue envuelta en una manta enorme hasta que se calmó.'::text),
(337523,37503,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment elle ... dans une énorme couverture jusqu''à ce qu''elle soit calme.'::text,'a été enveloppée'::text,'a enveloppé'::text,'est enveloppée'::text,'Attends, apparemment elle a été enveloppée dans une énorme couverture jusqu''à ce qu''elle soit calme.'::text),
(337526,37503,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur bir dakika, duyduğuma göre sakinleşene kadar kocaman bir battaniyeye ...'::text,'sarılmış'::text,'sarmış'::text,'sarılıyor'::text,'Dur bir dakika, duyduğuma göre sakinleşene kadar kocaman bir battaniyeye sarılmış.'::text),
(337527,37503,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag egy óriási takaróba ..., amíg meg nem nyugodott.'::text,'bebugyolálták'::text,'bebugyolált'::text,'bebugyolálják'::text,'Várj, állítólag egy óriási takaróba bebugyolálták, amíg meg nem nyugodott.'::text),
(337530,37504,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, ihre beste Freundin ... die Decke und hielt sie ruhig.'::text,'brachte'::text,'wurde gebracht'::text,'bringend'::text,'Hör mal, ich hab gehört, ihre beste Freundin brachte die Decke und hielt sie ruhig.'::text),
(337534,37504,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що її найкраща подруга ... ковдру і заспокоювала її.'::text,'принесла'::text,'була принесена'::text,'приносячи'::text,'Слухай, я чула, що її найкраща подруга принесла ковдру і заспокоювала її.'::text),
(337533,37504,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, he oído que su mejor amiga ... la manta y la mantuvo tranquila.'::text,'trajo'::text,'fue traída'::text,'trayendo'::text,'Oye, he oído que su mejor amiga trajo la manta y la mantuvo tranquila.'::text),
(337532,37504,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire que sa meilleure amie ... la couverture et l''a aidée à rester calme.'::text,'a apporté'::text,'a été apportée'::text,'apportant'::text,'Écoute, j''ai entendu dire que sa meilleure amie a apporté la couverture et l''a aidée à rester calme.'::text),
(337535,37504,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre en yakın arkadaşı battaniyeyi ... ve onu sakin tutmuş.'::text,'getirmiş'::text,'getirilmiş'::text,'getirerek'::text,'Dinle, duyduğuma göre en yakın arkadaşı battaniyeyi getirmiş ve onu sakin tutmuş.'::text),
(337536,37504,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy a legjobb barátnője ... a takarót, és megnyugtatta.'::text,'hozta el'::text,'el lett hozva'::text,'hozva'::text,'Figyelj, azt hallottam, hogy a legjobb barátnője hozta el a takarót, és megnyugtatta.'::text),
(337539,37505,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also, sie lächelt jetzt, also ... sie wohl wieder ruhig sein.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Okay, also, sie lächelt jetzt, also muss sie wohl wieder ruhig sein.'::text),
(337543,37505,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ну короче, вона зараз усміхається, тож, мабуть, вона ... знову бути спокійною.'::text,'мусить'::text,'не може'::text,'не повинна'::text,'Ну короче, вона зараз усміхається, тож, мабуть, вона мусить знову бути спокійною.'::text),
(337542,37505,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues ahora sonríe, así que al parecer ... estar tranquila otra vez.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'Vale, pues ahora sonríe, así que al parecer debe de estar tranquila otra vez.'::text),
(337541,37505,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, elle sourit maintenant, donc apparemment elle ... être de nouveau calme.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Bon alors, elle sourit maintenant, donc apparemment elle doit être de nouveau calme.'::text),
(337544,37505,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, şimdi gülümsüyor, yani demek ki yine sakin ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Tamam, şimdi gülümsüyor, yani demek ki yine sakin olmalı.'::text),
(337545,37505,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval most mosolyog, úgyhogy ... újra nyugodt.'::text,'biztosan'::text,'nem lehet'::text,'nem kéne'::text,'Oké, szóval most mosolyog, úgyhogy biztosan újra nyugodt.'::text),
(332679,36965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... im Hinterhof Wurst, als die Flammen hochschlugen. Makellose Kochkunst.'::text,'grillte gerade'::text,'grillte'::text,'hat gegrillt'::text,'Er grillte gerade im Hinterhof Wurst, als die Flammen hochschlugen. Makellose Kochkunst.'::text),
(332683,36965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... ковбаску на задньому дворі, коли спалахнуло полум''я. Бездоганна кухня.'::text,'смажив'::text,'підсмажив'::text,'підсмажив'::text,'Він смажив ковбаску на задньому дворі, коли спалахнуло полум''я. Бездоганна кухня.'::text),
(332682,36965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... salchicha en el patio trasero cuando las llamas saltaron. Una cocina impecable.'::text,'Estaba asando'::text,'Asó'::text,'Ha asado'::text,'Estaba asando salchicha en el patio trasero cuando las llamas saltaron. Una cocina impecable.'::text),
(332681,36965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... de la saucisse dans l''arrière-cour quand les flammes ont jailli. Une cuisine parfaite.'::text,'faisait griller'::text,'a fait griller'::text,'a fait griller'::text,'Il faisait griller de la saucisse dans l''arrière-cour quand les flammes ont jailli. Une cuisine parfaite.'::text),
(332684,36965,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arka bahçede sucuk ... alevler birden fışkırdı. Kusursuz aşçılık.'::text,'pişirirken'::text,'pişirdi'::text,'pişirmiş'::text,'Arka bahçede sucuk pişirirken alevler birden fışkırdı. Kusursuz aşçılık.'::text),
(332685,36965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kolbászt ... a hátsó udvarban, amikor felcsaptak a lángok. Hibátlan főzés.'::text,'sütött épp'::text,'megsütött'::text,'megsütött'::text,'Kolbászt sütött épp a hátsó udvarban, amikor felcsaptak a lángok. Hibátlan főzés.'::text),
(332688,36966,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit fünf Uhr im Hinterhof Würstchen.'::text,'grillt'::text,'grillt gerade'::text,'grillt'::text,'Er grillt seit fünf Uhr im Hinterhof Würstchen.'::text),
(332692,36966,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... ковбаски на задньому дворі з п''ятої години.'::text,'смажить'::text,'смажить'::text,'смажить'::text,'Він смажить ковбаски на задньому дворі з п''ятої години.'::text),
(332691,36966,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... salchichas en el patio trasero desde las cinco.'::text,'Lleva asando'::text,'Está asando'::text,'Asa'::text,'Lleva asando salchichas en el patio trasero desde las cinco.'::text),
(332690,36966,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des saucisses dans l''arrière-cour depuis cinq heures.'::text,'fait griller'::text,'est en train de faire griller'::text,'fait griller'::text,'Il fait griller des saucisses dans l''arrière-cour depuis cinq heures.'::text),
(332693,36966,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat beşten beri arka bahçede sucuk ...'::text,'pişiriyor'::text,'pişiriyor'::text,'pişirir'::text,'Saat beşten beri arka bahçede sucuk pişiriyor.'::text),
(332694,36966,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öt óra óta ... kolbászt a hátsó udvarban.'::text,'süt'::text,'süt'::text,'süt'::text,'Öt óra óta süt kolbászt a hátsó udvarban.'::text),
(332697,36967,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während seine Freunde im Hinterhof ..., hob er ein Stück Wurst hoch.'::text,'quatschten'::text,'quatschten'::text,'gequatscht haben'::text,'Während seine Freunde im Hinterhof quatschten, hob er ein Stück Wurst hoch.'::text),
(332701,36967,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки його друзі ... на задньому дворі, він підняв шматок ковбаски.'::text,'балакали'::text,'побалакали'::text,'побалакали'::text,'Поки його друзі балакали на задньому дворі, він підняв шматок ковбаски.'::text),
(332700,36967,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras sus amigos ... en el patio trasero, él levantó un trozo de salchicha.'::text,'charlaban'::text,'charlaron'::text,'han charlado'::text,'Mientras sus amigos charlaban en el patio trasero, él levantó un trozo de salchicha.'::text),
(332699,36967,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que ses potes ... dans l''arrière-cour, il a soulevé un morceau de saucisse.'::text,'discutaient'::text,'discutèrent'::text,'ont discuté'::text,'Pendant que ses potes discutaient dans l''arrière-cour, il a soulevé un morceau de saucisse.'::text),
(332702,36967,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları arka bahçede ..., o bir parça sucuk kaldırdı.'::text,'sohbet ederken'::text,'sohbet etti'::text,'sohbet etmiş'::text,'Arkadaşları arka bahçede sohbet ederken, o bir parça sucuk kaldırdı.'::text),
(332703,36967,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a barátai a hátsó udvarban ..., ő felemelt egy darab kolbászt.'::text,'beszélgettek'::text,'elbeszélgettek'::text,'beszélgettek már'::text,'Miközben a barátai a hátsó udvarban beszélgettek, ő felemelt egy darab kolbászt.'::text),
(332715,36969,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor die Freunde kamen, ... die Flammen das halbe Abendessen im Hinterhof verbrannt. Katastrophe!'::text,'hatten'::text,'haben'::text,'verbrennen'::text,'Bevor die Freunde kamen, hatten die Flammen das halbe Abendessen im Hinterhof verbrannt. Katastrophe!'::text),
(332719,36969,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ще до приходу друзів полум''я ... половину вечері на задньому дворі. Катастрофа!'::text,'спалило'::text,'спалило'::text,'палить'::text,'Ще до приходу друзів полум''я спалило половину вечері на задньому дворі. Катастрофа!'::text),
(332718,36969,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que llegaran los amigos, las llamas ... media cena del patio trasero. ¡Desastre!'::text,'habían quemado'::text,'han quemado'::text,'queman'::text,'Antes de que llegaran los amigos, las llamas habían quemado media cena del patio trasero. ¡Desastre!'::text),
(332717,36969,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant que les amis arrivent, les flammes ... la moitié du dîner dans l''arrière-cour. Catastrophe !'::text,'avaient brûlé'::text,'ont brûlé'::text,'brûlent'::text,'Avant que les amis arrivent, les flammes avaient brûlé la moitié du dîner dans l''arrière-cour. Catastrophe !'::text),
(332720,36969,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlar gelmeden önce alevler ... arka bahçedeki yemeğin yarısını. Felaket!'::text,'yakmıştı'::text,'yaktı'::text,'yakıyor'::text,'Arkadaşlar gelmeden önce alevler yakmıştı arka bahçedeki yemeğin yarısını. Felaket!'::text),
(332721,36969,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a barátok megérkeztek, a lángok ... a hátsó udvari vacsora felét. Katasztrófa!'::text,'elégették'::text,'elégették'::text,'égetik'::text,'Mielőtt a barátok megérkeztek, a lángok elégették a hátsó udvari vacsora felét. Katasztrófa!'::text),
(332724,36970,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, der Typ, ... in dem Hinterhof grillt, hat mir gesagt, dass er nie etwas anbrennen lässt.'::text,'der'::text,'was'::text,'dessen'::text,'Süße, der Typ, der in dem Hinterhof grillt, hat mir gesagt, dass er nie etwas anbrennen lässt.'::text),
(332728,36970,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, хлопець, ... смажить на грилі на тому задньому дворі, сказав мені, що ніколи нічого не палить.'::text,'який'::text,'що'::text,'чий'::text,'Подруго, хлопець, який смажить на грилі на тому задньому дворі, сказав мені, що ніколи нічого не палить.'::text),
(332727,36970,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, el chico ... asa carne en ese patio trasero me dijo que nunca quema nada.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Tía, el chico que asa carne en ese patio trasero me dijo que nunca quema nada.'::text),
(332726,36970,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, le mec ... fait les grillades dans cette arrière-cour m''a dit qu''il ne brûle jamais rien.'::text,'qui'::text,'que'::text,'dont'::text,'Meuf, le mec qui fait les grillades dans cette arrière-cour m''a dit qu''il ne brûle jamais rien.'::text),
(332729,36970,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o arka bahçede ızgara yapan adam ... bana hiçbir şeyi yakmadığını söyledi.'::text,''::text,NULL::text,NULL::text,'Kızım, o arka bahçede ızgara yapan adam bana hiçbir şeyi yakmadığını söyledi.'::text),
(332730,36970,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a srác, ... abban a hátsó udvarban grillezik, azt mondta, hogy soha nem éget oda semmit.'::text,'aki'::text,'ami'::text,'akinek a'::text,'Csajszi, a srác, aki abban a hátsó udvarban grillezik, azt mondta, hogy soha nem éget oda semmit.'::text),
(332733,36971,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er hat mir erzählt, dass er die Wurst am Tag vor der Hinterhofparty selbst ...'::text,'gemacht hatte'::text,'gemacht hat'::text,'macht'::text,'Bestie, er hat mir erzählt, dass er die Wurst am Tag vor der Hinterhofparty selbst gemacht hatte.'::text),
(332737,36971,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що ... ту ковбасу сам за день до вечірки на задньому дворі.'::text,'зробив'::text,'зробив'::text,'робить'::text,'Подруго, він сказав мені, що зробив ту ковбасу сам за день до вечірки на задньому дворі.'::text),
(332736,36971,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ... la salchicha él mismo el día antes de la fiesta en el patio.'::text,'había hecho'::text,'ha hecho'::text,'hace'::text,'Amiga, me dijo que había hecho la salchicha él mismo el día antes de la fiesta en el patio.'::text),
(332735,36971,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma bestie, il m''a dit qu''il ... la saucisse lui-même la veille de la fête dans l''arrière-cour.'::text,'avait fait'::text,'a fait'::text,'fait'::text,'Ma bestie, il m''a dit qu''il avait fait la saucisse lui-même la veille de la fête dans l''arrière-cour.'::text),
(332738,36971,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana sucuğu arka bahçe partisinden bir gün önce kendisinin ... söyledi.'::text,'yapmış olduğunu'::text,'yaptığını'::text,'yaptığını'::text,'Kanka, bana sucuğu arka bahçe partisinden bir gün önce kendisinin yapmış olduğunu söyledi.'::text),
(332739,36971,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy a kolbászt a hátsó udvari buli előtti napon maga ...'::text,'készítette'::text,'készítette'::text,'készíti'::text,'Csajszi, azt mondta, hogy a kolbászt a hátsó udvari buli előtti napon maga készítette.'::text),
(332742,36972,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich ... Barbecues vor dieser Hinterhofparty.'::text,'hasste er früher'::text,'hasste er früher'::text,'ist er es gewohnt zu hassen'::text,'Hör mal, angeblich hasste er früher Barbecues vor dieser Hinterhofparty.'::text),
(332746,36972,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він ... барбекю до цієї вечірки на задньому дворі.'::text,'раніше ненавидів'::text,'раніше ненавидів'::text,'звик ненавидіти'::text,'Слухай, кажуть, він раніше ненавидів барбекю до цієї вечірки на задньому дворі.'::text),
(332745,36972,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer antes de esta fiesta en el patio ... las barbacoas.'::text,'solía odiar'::text,'odiaba'::text,'está acostumbrado a odiar'::text,'Oye, al parecer antes de esta fiesta en el patio solía odiar las barbacoas.'::text),
(332744,36972,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il ... les barbecues avant cette fête dans l''arrière-cour.'::text,'détestait'::text,'détestait'::text,'a l''habitude de détester'::text,'Écoute, apparemment il détestait les barbecues avant cette fête dans l''arrière-cour.'::text),
(332747,36972,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre bu arka bahçe partisinden önce barbekülerden ...'::text,'nefret edermiş'::text,'nefret edermiş'::text,'nefret etmeye alışkınmış'::text,'Dinle, duyduğuma göre bu arka bahçe partisinden önce barbekülerden nefret edermiş.'::text),
(332748,36972,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag e hátsó udvari buli előtt ... a barbecue-kat.'::text,'régen utálta'::text,'utálta'::text,'hozzá van szokva, hogy utálja'::text,'Figyelj, állítólag e hátsó udvari buli előtt régen utálta a barbecue-kat.'::text),
(332751,36973,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast sichtlich Spaß am ... im Hinterhof für alle deine Freunde. Respekt.'::text,'Grillen'::text,'Grillen'::text,'Grillen'::text,'Du hast sichtlich Spaß am Grillen im Hinterhof für alle deine Freunde. Respekt.'::text),
(332755,36973,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тобі явно подобається ... на задньому дворі для всіх друзів. Респект.'::text,'готувати на грилі'::text,'готувати на грилі'::text,'готувати на грилі'::text,'Тобі явно подобається готувати на грилі на задньому дворі для всіх друзів. Респект.'::text),
(332754,36973,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está claro que te encanta ... en el patio trasero para todos tus amigos. Respeto.'::text,'hacer barbacoas'::text,'hacer barbacoas'::text,'hacer barbacoas'::text,'Está claro que te encanta hacer barbacoas en el patio trasero para todos tus amigos. Respeto.'::text),
(332753,36973,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'T''adores clairement ... dans l''arrière-cour pour tous tes potes. Respect.'::text,'faire des grillades'::text,'faire des grillades'::text,'faire des grillades'::text,'T''adores clairement faire des grillades dans l''arrière-cour pour tous tes potes. Respect.'::text),
(332756,36973,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki arka bahçede tüm arkadaşların için ... bayılıyorsun. Saygılar.'::text,'ızgara yapmaya'::text,'ızgara yapmaya'::text,'ızgara yapmak'::text,'Belli ki arka bahçede tüm arkadaşların için ızgara yapmaya bayılıyorsun. Saygılar.'::text),
(332757,36973,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Láthatóan imádsz ... a hátsó udvarban az összes barátodnak. Respekt.'::text,'grillezni'::text,'grillezni'::text,'grillezni'::text,'Láthatóan imádsz grillezni a hátsó udvarban az összes barátodnak. Respekt.'::text),
(332769,36975,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... eine Stunde lang Wurst, bevor im Hinterhof jemand die Flammen bemerkte. Super gemacht.'::text,'grillte schon'::text,'grillt schon'::text,'grillte'::text,'Er grillte schon eine Stunde lang Wurst, bevor im Hinterhof jemand die Flammen bemerkte. Super gemacht.'::text),
(332773,36975,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... ковбаску цілу годину, перш ніж хтось на задньому дворі помітив полум''я. Чудова робота.'::text,'смажив'::text,'смажить'::text,'смажив'::text,'Він смажив ковбаску цілу годину, перш ніж хтось на задньому дворі помітив полум''я. Чудова робота.'::text),
(332772,36975,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... salchicha durante una hora antes de que alguien en el patio viera las llamas. Buen trabajo.'::text,'Había estado asando'::text,'Ha estado asando'::text,'Estaba asando'::text,'Había estado asando salchicha durante una hora antes de que alguien en el patio viera las llamas. Buen trabajo.'::text),
(332771,36975,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... de la saucisse pendant une heure avant que quelqu''un dans l''arrière-cour remarque les flammes. Beau travail.'::text,'avait fait griller'::text,'a fait griller'::text,'faisait griller'::text,'Il avait fait griller de la saucisse pendant une heure avant que quelqu''un dans l''arrière-cour remarque les flammes. Beau travail.'::text),
(332774,36975,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arka bahçede biri alevleri fark edene kadar bir saattir ... sucuk. Harika iş.'::text,'pişiriyordu'::text,'pişiriyor'::text,'pişiriyordu'::text,'Arka bahçede biri alevleri fark edene kadar bir saattir pişiriyordu sucuk. Harika iş.'::text),
(332775,36975,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már egy órája ... a kolbászt, mire a hátsó udvarban bárki észrevette a lángokat. Szép munka.'::text,'sütötte'::text,'süti'::text,'sütötte'::text,'Már egy órája sütötte a kolbászt, mire a hátsó udvarban bárki észrevette a lángokat. Szép munka.'::text),
(371037,41227,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neonschilder ... über der Kreuzung, als sie ein Fingerherz machte.'::text,'leuchteten'::text,'leuchteten auf'::text,'haben geleuchtet'::text,'Neonschilder leuchteten über der Kreuzung, als sie ein Fingerherz machte.'::text),
(371041,41227,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Неонові вивіски ... над переходом, коли вона склала серце з пальців.'::text,'світилися'::text,'засвітилися'::text,'засвітилися'::text,'Неонові вивіски світилися над переходом, коли вона склала серце з пальців.'::text),
(371040,41227,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los letreros de neón ... sobre el cruce cuando ella hizo un corazón con los dedos.'::text,'brillaban'::text,'brillaron'::text,'han brillado'::text,'Los letreros de neón brillaban sobre el cruce cuando ella hizo un corazón con los dedos.'::text),
(371039,41227,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les enseignes au néon ... au-dessus du passage piéton quand elle a fait un cœur avec ses doigts.'::text,'brillaient'::text,'brillèrent'::text,'ont brillé'::text,'Les enseignes au néon brillaient au-dessus du passage piéton quand elle a fait un cœur avec ses doigts.'::text),
(371042,41227,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parmaklarıyla kalp yaptığında neon tabelalar geçidin üstünde ...'::text,'parlıyordu'::text,'parladı'::text,'parlamış'::text,'Parmaklarıyla kalp yaptığında neon tabelalar geçidin üstünde parlıyordu.'::text),
(371043,41227,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A neonfeliratok ... a zebra fölött, amikor ujjszívet mutatott.'::text,'világítottak'::text,'felvillantak'::text,'világítottak már'::text,'A neonfeliratok világítottak a zebra fölött, amikor ujjszívet mutatott.'::text),
(371046,41228,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie die Kreuzung erreichte, ... die Stadt schon alle ihre Neonschilder eingeschaltet.'::text,'hatte'::text,'hat'::text,'schaltet'::text,'Als sie die Kreuzung erreichte, hatte die Stadt schon alle ihre Neonschilder eingeschaltet.'::text),
(371050,41228,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона дійшла до переходу, місто вже ... всі свої неонові вивіски.'::text,'увімкнуло'::text,'увімкнуло'::text,'вмикає'::text,'Коли вона дійшла до переходу, місто вже увімкнуло всі свої неонові вивіски.'::text),
(371049,41228,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegó al cruce, la ciudad ya ... todos sus letreros de neón.'::text,'había encendido'::text,'ha encendido'::text,'enciende'::text,'Para cuando llegó al cruce, la ciudad ya había encendido todos sus letreros de neón.'::text),
(371048,41228,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle est arrivée au passage piéton, la ville ... toutes ses enseignes au néon.'::text,'avait allumé'::text,'a allumé'::text,'allume'::text,'Quand elle est arrivée au passage piéton, la ville avait allumé toutes ses enseignes au néon.'::text),
(371051,41228,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçide vardığında şehir tüm neon tabelalarını çoktan ...'::text,'yakmıştı'::text,'yaktı'::text,'yakıyor'::text,'Geçide vardığında şehir tüm neon tabelalarını çoktan yakmıştı.'::text),
(371052,41228,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a zebrához ért, a város már ... az összes neonfeliratát.'::text,'felkapcsolta'::text,'felkapcsolta'::text,'felkapcsolja'::text,'Mire a zebrához ért, a város már felkapcsolta az összes neonfeliratát.'::text),
(371055,41229,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie bis Mitternacht bleibt, ... sie noch mehr Neonschilder in der Stadt.'::text,'sieht'::text,'sähe'::text,'sah'::text,'Wenn sie bis Mitternacht bleibt, sieht sie noch mehr Neonschilder in der Stadt.'::text),
(371059,41229,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона залишиться до півночі, то ... ще більше неонових вивісок у місті.'::text,'побачить'::text,'побачила б'::text,'бачила'::text,'Якщо вона залишиться до півночі, то побачить ще більше неонових вивісок у місті.'::text),
(371058,41229,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se queda hasta medianoche, ... aún más letreros de neón en la ciudad.'::text,'verá'::text,'vería'::text,'vio'::text,'Si se queda hasta medianoche, verá aún más letreros de neón en la ciudad.'::text),
(371057,41229,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle reste jusqu''à minuit, elle ... encore plus d''enseignes au néon dans la ville.'::text,'verra'::text,'verrait'::text,'a vu'::text,'Si elle reste jusqu''à minuit, elle verra encore plus d''enseignes au néon dans la ville.'::text),
(371060,41229,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısına kadar kalırsa şehirde daha da fazla neon tabela ...'::text,'görecek'::text,'görürdü'::text,'gördü'::text,'Gece yarısına kadar kalırsa şehirde daha da fazla neon tabela görecek.'::text),
(371061,41229,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha éjfélig marad, még több neonfeliratot ... a városban.'::text,'fog látni'::text,'látna'::text,'látott'::text,'Ha éjfélig marad, még több neonfeliratot fog látni a városban.'::text),
(371073,41231,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die ganze Straße ... von Neonlicht, natürlich nur für ihr Fingerherz.'::text,'ist bedeckt'::text,'bedeckt'::text,'bedeckt gerade'::text,'Die ganze Straße ist bedeckt von Neonlicht, natürlich nur für ihr Fingerherz.'::text),
(371077,41231,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уся вулиця ... неоновим світлом, звісно ж, лише заради її серця з пальців.'::text,'залита'::text,'заливає'::text,'заливає'::text,'Уся вулиця залита неоновим світлом, звісно ж, лише заради її серця з пальців.'::text),
(371076,41231,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toda la calle ... de luz de neón, obviamente solo por su corazón con los dedos.'::text,'está cubierta'::text,'cubre'::text,'está cubriendo'::text,'Toda la calle está cubierta de luz de neón, obviamente solo por su corazón con los dedos.'::text),
(371075,41231,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toute la rue ... de lumière néon, évidemment rien que pour son cœur avec les doigts.'::text,'est couverte'::text,'couvre'::text,'est en train de couvrir'::text,'Toute la rue est couverte de lumière néon, évidemment rien que pour son cœur avec les doigts.'::text),
(371078,41231,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün sokak neon ışıkla ..., tabii ki sadece onun parmak kalbi için.'::text,'kaplı'::text,'kaplıyor'::text,'kaplıyor'::text,'Bütün sokak neon ışıkla kaplı, tabii ki sadece onun parmak kalbi için.'::text),
(371079,41231,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész utca ... neonfénnyel, nyilván csak az ujjszíve kedvéért.'::text,'be van borítva'::text,'beborít'::text,'éppen beborít'::text,'Az egész utca be van borítva neonfénnyel, nyilván csak az ujjszíve kedvéért.'::text),
(371082,41232,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich schüchtern ... die Neonschilder jede Hausfassade in Rot, Blau und Gelb.'::text,'tauchen'::text,'werden getaucht'::text,'tauchend'::text,'Offensichtlich schüchtern tauchen die Neonschilder jede Hausfassade in Rot, Blau und Gelb.'::text),
(371086,41232,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно сором''язливі неонові вивіски ... кожен фасад червоним, синім і жовтим.'::text,'покривають'::text,'покриті'::text,'покриваючи'::text,'Явно сором''язливі неонові вивіски покривають кожен фасад червоним, синім і жовтим.'::text),
(371085,41232,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente tímidos, los letreros de neón ... cada fachada de rojo, azul y amarillo.'::text,'cubren'::text,'son cubiertos'::text,'cubriendo'::text,'Claramente tímidos, los letreros de neón cubren cada fachada de rojo, azul y amarillo.'::text),
(371084,41232,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Visiblement timides, les enseignes au néon ... chaque façade de rouge, de bleu et de jaune.'::text,'couvrent'::text,'sont couvertes'::text,'couvrant'::text,'Visiblement timides, les enseignes au néon couvrent chaque façade de rouge, de bleu et de jaune.'::text),
(371087,41232,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki utangaç olan neon tabelalar her bina cephesini kırmızı, mavi ve sarıyla ...'::text,'kaplıyor'::text,'kaplanıyor'::text,'kaplayan'::text,'Belli ki utangaç olan neon tabelalar her bina cephesini kırmızı, mavi ve sarıyla kaplıyor.'::text),
(371088,41232,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A láthatóan félénk neonfeliratok minden homlokzatot ... pirossal, kékkel és sárgával.'::text,'beborítanak'::text,'be vannak borítva'::text,'beborítva'::text,'A láthatóan félénk neonfeliratok minden homlokzatot beborítanak pirossal, kékkel és sárgával.'::text),
(371091,41233,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Neonlichter ... an dieser Kreuzung absolut blendend sein!'::text,'müssen'::text,'können nicht'::text,'dürfen nicht'::text,'Diese Neonlichter müssen an dieser Kreuzung absolut blendend sein!'::text),
(371095,41233,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці неонові вогні ... бути на цьому переході просто сліпучими!'::text,'мусять'::text,'не можуть'::text,'не повинні'::text,'Ці неонові вогні мусять бути на цьому переході просто сліпучими!'::text),
(371094,41233,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esas luces de neón ... ser totalmente cegadoras en este cruce!'::text,'deben de'::text,'no pueden'::text,'no deben'::text,'¡Esas luces de neón deben de ser totalmente cegadoras en este cruce!'::text),
(371093,41233,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces néons ... être complètement aveuglants à ce passage piéton !'::text,'doivent'::text,'ne peuvent pas'::text,'ne doivent pas'::text,'Ces néons doivent être complètement aveuglants à ce passage piéton !'::text),
(371096,41233,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O neon ışıklar bu geçitte kesinlikle göz kamaştırıcı ...!'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'O neon ışıklar bu geçitte kesinlikle göz kamaştırıcı olmalı!'::text),
(371097,41233,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azoknak a neonfényeknek ... elképesztően vakítónak lenniük ennél a zebránál!'::text,'kell'::text,'nem lehet'::text,'nem szabad'::text,'Azoknak a neonfényeknek kell elképesztően vakítónak lenniük ennél a zebránál!'::text),
(371100,41234,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kreuzung, ... Neonschilder nie ausgehen, ist buchstäblich ein Albtraum für den Schlaf!'::text,'deren'::text,'die'::text,'welche'::text,'Die Kreuzung, deren Neonschilder nie ausgehen, ist buchstäblich ein Albtraum für den Schlaf!'::text),
(371104,41234,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перехрестя, ... неонові вивіски ніколи не вимикаються, — це буквально жах для сну!'::text,'чиї'::text,'яке'::text,'що'::text,'Перехрестя, чиї неонові вивіски ніколи не вимикаються, — це буквально жах для сну!'::text),
(371103,41234,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El cruce ... letreros de neón nunca se apagan es literalmente una pesadilla para dormir!'::text,'cuyos'::text,'que'::text,'el cual'::text,'¡El cruce cuyos letreros de neón nunca se apagan es literalmente una pesadilla para dormir!'::text),
(371102,41234,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le carrefour ... les enseignes au néon ne s''éteignent jamais est littéralement un cauchemar pour dormir !'::text,'dont'::text,'qui'::text,'que'::text,'Le carrefour dont les enseignes au néon ne s''éteignent jamais est littéralement un cauchemar pour dormir !'::text),
(371105,41234,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neon tabelaları hiç sönmeyen kavşak ... uyku için resmen bir kâbus!'::text,''::text,NULL::text,NULL::text,'Neon tabelaları hiç sönmeyen kavşak uyku için resmen bir kâbus!'::text),
(371106,41234,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a kereszteződés, ... neonfeliratai sosem kapcsolnak ki, szó szerint rémálom az alváshoz!'::text,'amelynek a'::text,'aki'::text,'amely'::text,'Az a kereszteződés, amelynek a neonfeliratai sosem kapcsolnak ki, szó szerint rémálom az alváshoz!'::text),
(371109,41235,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, Seoul, ... Neonschilder nie ausgehen, ist ihre Lieblingsstadt, hat sie gesagt.'::text,'dessen'::text,'welches'::text,'das'::text,'Bestie, Seoul, dessen Neonschilder nie ausgehen, ist ihre Lieblingsstadt, hat sie gesagt.'::text),
(371113,41235,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, Сеул, ... неонові вивіски ніколи не вимикаються, — її улюблене місто, так вона сказала.'::text,'чиї'::text,'який'::text,'що'::text,'Подруго, Сеул, чиї неонові вивіски ніколи не вимикаються, — її улюблене місто, так вона сказала.'::text),
(371112,41235,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, Seúl, ... letreros de neón nunca se apagan, es su ciudad favorita, según dijo.'::text,'cuyos'::text,'la cual'::text,'que'::text,'Amiga, Seúl, cuyos letreros de neón nunca se apagan, es su ciudad favorita, según dijo.'::text),
(371111,41235,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma bestie, Séoul, ... les enseignes au néon ne s''éteignent jamais, est sa ville préférée, d''après elle.'::text,'dont'::text,'qui'::text,'que'::text,'Ma bestie, Séoul, dont les enseignes au néon ne s''éteignent jamais, est sa ville préférée, d''après elle.'::text),
(371114,41235,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, neon tabelaları hiç sönmeyen Seul ... onun en sevdiği şehirmiş, öyle dedi.'::text,''::text,NULL::text,NULL::text,'Kanka, neon tabelaları hiç sönmeyen Seul onun en sevdiği şehirmiş, öyle dedi.'::text),
(371115,41235,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, Szöul, ... neonfeliratai sosem kapcsolnak ki, a kedvenc városa, azt mondta.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'Csajszi, Szöul, amelynek a neonfeliratai sosem kapcsolnak ki, a kedvenc városa, azt mondta.'::text),
(371127,41237,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, bis Mitternacht wird sie jede Neonstraße der Stadt ..., ohne Witz.'::text,'gesehen haben'::text,'sehen'::text,'sehen'::text,'Bro, bis Mitternacht wird sie jede Neonstraße der Stadt gesehen haben, ohne Witz.'::text),
(371131,41237,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до півночі вона ... кожну неонову вулицю в місті, без брехні.'::text,'побачить'::text,'побачить'::text,'бачить'::text,'Бро, до півночі вона побачить кожну неонову вулицю в місті, без брехні.'::text),
(371130,41237,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para medianoche ... todas las calles de neón de la ciudad, en serio.'::text,'habrá visto'::text,'verá'::text,'ve'::text,'Bro, para medianoche habrá visto todas las calles de neón de la ciudad, en serio.'::text),
(371129,41237,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, d''ici minuit, elle ... toutes les rues néon de la ville, sans mentir.'::text,'aura vu'::text,'verra'::text,'voit'::text,'Frérot, d''ici minuit, elle aura vu toutes les rues néon de la ville, sans mentir.'::text),
(371132,41237,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gece yarısına kadar şehirdeki her neon sokağı ..., yemin ederim.'::text,'görmüş olacak'::text,'görecek'::text,'görüyor'::text,'Kanka, gece yarısına kadar şehirdeki her neon sokağı görmüş olacak, yemin ederim.'::text),
(371133,41237,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, éjfélre ... a város összes neonos utcáját, komolyan.'::text,'megnézi'::text,'meg fogja nézni'::text,'nézi'::text,'Tesó, éjfélre megnézi a város összes neonos utcáját, komolyan.'::text),
(345432,38382,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit wird sie sich in einer anderen Stadt ..., und ihre Locken werden völlig wild sein!'::text,'gerade im Kreis drehen'::text,'im Kreis drehen'::text,'dreht sich'::text,'Morgen um diese Zeit wird sie sich in einer anderen Stadt gerade im Kreis drehen, und ihre Locken werden völlig wild sein!'::text),
(345436,38382,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона ... в іншому місті, і її кучеряве волосся буде просто шаленим!'::text,'кружлятиме'::text,'закружляє'::text,'кружляє'::text,'Завтра в цей час вона кружлятиме в іншому місті, і її кучеряве волосся буде просто шаленим!'::text),
(345435,38382,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora ... en otra ciudad, y su pelo rizado estará totalmente salvaje!'::text,'estará girando'::text,'girará'::text,'gira'::text,'¡Mañana a esta hora estará girando en otra ciudad, y su pelo rizado estará totalmente salvaje!'::text),
(345434,38382,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... dans une autre ville, et ses cheveux bouclés seront complètement fous !'::text,'sera en train de tournoyer'::text,'tournoiera'::text,'tournoie'::text,'Demain à la même heure, elle sera en train de tournoyer dans une autre ville, et ses cheveux bouclés seront complètement fous !'::text),
(345437,38382,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde başka bir şehirde ... ve kıvırcık saçları çılgına dönecek!'::text,'dönüyor olacak'::text,'dönecek'::text,'dönüyor'::text,'Yarın bu saatlerde başka bir şehirde dönüyor olacak ve kıvırcık saçları çılgına dönecek!'::text),
(345438,38382,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor egy másik városban ..., és a göndör haja teljesen megvadul!'::text,'fog pörögni'::text,'megpördül'::text,'pörög'::text,'Holnap ilyenkor egy másik városban fog pörögni, és a göndör haja teljesen megvadul!'::text),
(345441,38383,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schwört, sie ... nie wieder ihre Locken glätten. Niemals!'::text,'wird'::text,'wird'::text,'wird'::text,'Sie schwört, sie wird nie wieder ihre Locken glätten. Niemals!'::text),
(345445,38383,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона клянеться, що більше ніколи ... своє кучеряве волосся. Ніколи!'::text,'не випрямить'::text,'не випрямлятиме'::text,'не випрямляє'::text,'Вона клянеться, що більше ніколи не випрямить своє кучеряве волосся. Ніколи!'::text),
(345444,38383,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jura que nunca más ... su pelo rizado. ¡Jamás!'::text,'se alisará'::text,'se estará alisando'::text,'se alisa'::text,'Jura que nunca más se alisará su pelo rizado. ¡Jamás!'::text),
(345443,38383,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle jure qu''elle ... plus jamais ses cheveux bouclés. Jamais !'::text,'ne lissera'::text,'ne sera en train de lisser'::text,'ne lisse'::text,'Elle jure qu''elle ne lissera plus jamais ses cheveux bouclés. Jamais !'::text),
(345446,38383,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kıvırcık saçlarını bir daha asla ... yemin ediyor. Asla!'::text,'düzleştirmeyeceğine'::text,'düzleştiriyor olmayacağına'::text,'düzleştirmediğine'::text,'Kıvırcık saçlarını bir daha asla düzleştirmeyeceğine yemin ediyor. Asla!'::text),
(345447,38383,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megesküszik, hogy soha többé ... a göndör haját. Soha!'::text,'nem egyenesíti ki'::text,'nem fogja kiegyenesíteni'::text,'nem egyenesíti éppen ki'::text,'Megesküszik, hogy soha többé nem egyenesíti ki a göndör haját. Soha!'::text),
(345450,38384,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Luft feucht ..., werden ihre Locken noch größer.'::text,'ist'::text,'sein wird'::text,'war'::text,'Wenn die Luft feucht ist, werden ihre Locken noch größer.'::text),
(345454,38384,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли повітря ... вологим, її кучеряве волосся стає ще пишнішим.'::text,'буває'::text,'буде'::text,'було'::text,'Коли повітря буває вологим, її кучеряве волосся стає ще пишнішим.'::text),
(345453,38384,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el aire ... húmedo, su pelo rizado se pone aún más grande.'::text,'está'::text,'estará'::text,'estaba'::text,'Si el aire está húmedo, su pelo rizado se pone aún más grande.'::text),
(345452,38384,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''air ... humide, ses cheveux bouclés deviennent encore plus volumineux.'::text,'est'::text,'sera'::text,'était'::text,'Si l''air est humide, ses cheveux bouclés deviennent encore plus volumineux.'::text),
(345455,38384,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hava nemli ..., kıvırcık saçları daha da kabarır.'::text,'olursa'::text,'olacaksa'::text,'olduysa'::text,'Hava nemli olursa, kıvırcık saçları daha da kabarır.'::text),
(345456,38384,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a levegő párás ..., a göndör haja még dúsabb lesz.'::text,''::text,'lesz'::text,'volt'::text,'Ha a levegő párás, a göndör haja még dúsabb lesz.'::text),
(345459,38385,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie wieder lacht, ... ihre Locken um ihr Gesicht.'::text,'hüpfen'::text,'würden hüpfen'::text,'hüpften'::text,'Wenn sie wieder lacht, hüpfen ihre Locken um ihr Gesicht.'::text),
(345463,38385,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона знову засміється, її кучері ... навколо обличчя.'::text,'підстрибнуть'::text,'підстрибнули б'::text,'підстрибнули'::text,'Якщо вона знову засміється, її кучері підстрибнуть навколо обличчя.'::text),
(345462,38385,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si vuelve a reírse, su pelo rizado ... alrededor de su cara.'::text,'rebotará'::text,'rebotaría'::text,'rebotó'::text,'Si vuelve a reírse, su pelo rizado rebotará alrededor de su cara.'::text),
(345461,38385,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle rit encore, ses cheveux bouclés ... autour de son visage.'::text,'rebondiront'::text,'rebondiraient'::text,'ont rebondi'::text,'Si elle rit encore, ses cheveux bouclés rebondiront autour de son visage.'::text),
(345464,38385,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yine gülerse kıvırcık saçları yüzünün etrafında ...'::text,'zıplayacak'::text,'zıplardı'::text,'zıpladı'::text,'Yine gülerse kıvırcık saçları yüzünün etrafında zıplayacak.'::text),
(345465,38385,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha megint nevet, a göndör haja ... az arca körül.'::text,'ugrálni fog'::text,'ugrálna'::text,'ugrált'::text,'Ha megint nevet, a göndör haja ugrálni fog az arca körül.'::text),
(345468,38386,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn ich solche Locken hätte wie sie, ... ich sie nie abschneiden, echt.'::text,'würde'::text,'werde'::text,'habe'::text,'Bro, wenn ich solche Locken hätte wie sie, würde ich sie nie abschneiden, echt.'::text),
(345472,38386,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби в мене було таке кучеряве волосся, як у неї, я ... його, чесно.'::text,'ніколи б не стриг'::text,'ніколи не стригтиму'::text,'ніколи не стриг'::text,'Бро, якби в мене було таке кучеряве волосся, як у неї, я ніколи б не стриг його, чесно.'::text),
(345471,38386,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si tuviera el pelo rizado como ella, ..., en serio.'::text,'nunca me lo cortaría'::text,'nunca me lo cortaré'::text,'nunca me lo corté'::text,'Bro, si tuviera el pelo rizado como ella, nunca me lo cortaría, en serio.'::text),
(345470,38386,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si j''avais des cheveux bouclés comme les siens, je ne ... jamais, sérieux.'::text,'les couperais'::text,'les couperai'::text,'les ai coupés'::text,'Frérot, si j''avais des cheveux bouclés comme les siens, je ne les couperais jamais, sérieux.'::text),
(345473,38386,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onunki gibi kıvırcık saçlarım olsaydı asla ..., cidden.'::text,'kestirmezdim'::text,'kestirmeyeceğim'::text,'kestirmedim'::text,'Kanka, onunki gibi kıvırcık saçlarım olsaydı asla kestirmezdim, cidden.'::text),
(345474,38386,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nekem is ilyen göndör hajam lenne, ..., komolyan.'::text,'soha nem vágatnám le'::text,'soha nem fogom levágatni'::text,'soha nem vágattam le'::text,'Tesó, ha nekem is ilyen göndör hajam lenne, soha nem vágatnám le, komolyan.'::text),
(345477,38387,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern bei Sonnenuntergang ... ihre Locken vom Wind auf dem Dach zerzaust.'::text,'wurden'::text,'werden'::text,'wehten'::text,'Gestern bei Sonnenuntergang wurden ihre Locken vom Wind auf dem Dach zerzaust.'::text),
(345481,38387,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора на заході сонця її кучері ... вітром на даху.'::text,'були розтріпані'::text,'розтріпуються'::text,'розвівалися'::text,'Учора на заході сонця її кучері були розтріпані вітром на даху.'::text),
(345480,38387,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer al atardecer, su pelo rizado ... por el viento de la azotea.'::text,'fue alborotado'::text,'es alborotado'::text,'sopló'::text,'Ayer al atardecer, su pelo rizado fue alborotado por el viento de la azotea.'::text),
(345479,38387,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier au coucher du soleil, ses cheveux bouclés ... par le vent sur le toit.'::text,'ont été ébouriffés'::text,'sont ébouriffés'::text,'ont soufflé'::text,'Hier au coucher du soleil, ses cheveux bouclés ont été ébouriffés par le vent sur le toit.'::text),
(345482,38387,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün gün batımında kıvırcık saçları çatıdaki rüzgârla ...'::text,'savruldu'::text,'savrulur'::text,'savurdu'::text,'Dün gün batımında kıvırcık saçları çatıdaki rüzgârla savruldu.'::text),
(345483,38387,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap naplementekor a göndör haja ... a tetőn fújó széltől.'::text,'össze lett kócolva'::text,'össze van kócolva'::text,'fújt'::text,'Tegnap naplementekor a göndör haja össze lett kócolva a tetőn fújó széltől.'::text),
(345486,38388,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im letzten Quartal ... sie ein Budget für die Pflege ihrer Locken für die ganze Reise.'::text,'plante'::text,'wurde geplant'::text,'planend'::text,'Im letzten Quartal plante sie ein Budget für die Pflege ihrer Locken für die ganze Reise.'::text),
(345490,38388,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулого кварталу вона ... бюджет на догляд за кучерявим волоссям на всю поїздку.'::text,'запланувала'::text,'була запланована'::text,'плануючи'::text,'Минулого кварталу вона запланувала бюджет на догляд за кучерявим волоссям на всю поїздку.'::text),
(345489,38388,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El trimestre pasado ... un presupuesto para el cuidado de su pelo rizado para todo el viaje.'::text,'planificó'::text,'fue planificado'::text,'planificando'::text,'El trimestre pasado planificó un presupuesto para el cuidado de su pelo rizado para todo el viaje.'::text),
(345488,38388,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le trimestre dernier, elle ... un budget soins pour cheveux bouclés pour tout le voyage.'::text,'a planifié'::text,'a été planifié'::text,'planifiant'::text,'Le trimestre dernier, elle a planifié un budget soins pour cheveux bouclés pour tout le voyage.'::text),
(345491,38388,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen çeyrekte tüm gezi için kıvırcık saç bakımı bütçesi ...'::text,'planladı'::text,'planlandı'::text,'planlayan'::text,'Geçen çeyrekte tüm gezi için kıvırcık saç bakımı bütçesi planladı.'::text),
(345492,38388,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az előző negyedévben ... egy göndörhaj-ápolási költségvetést az egész útra.'::text,'tervezett'::text,'tervezve lett'::text,'tervezve'::text,'Az előző negyedévben tervezett egy göndörhaj-ápolási költségvetést az egész útra.'::text),
(345504,38390,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... Locken hüpfen, lacht an der Bar.'::text,'deren'::text,'die'::text,'was'::text,'Die Frau, deren Locken hüpfen, lacht an der Bar.'::text),
(345508,38390,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... кучері підстрибують, сміється біля бару.'::text,'чиї'::text,'яка'::text,'що'::text,'Жінка, чиї кучері підстрибують, сміється біля бару.'::text),
(345507,38390,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... pelo rizado rebota se ríe en el bar.'::text,'cuyo'::text,'que'::text,'la cual'::text,'La mujer cuyo pelo rizado rebota se ríe en el bar.'::text),
(345506,38390,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... les cheveux bouclés rebondissent rit au bar.'::text,'dont'::text,'qui'::text,'que'::text,'La femme dont les cheveux bouclés rebondissent rit au bar.'::text),
(345509,38390,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kıvırcık saçları zıplayan kadın ... barda gülüyor.'::text,''::text,NULL::text,NULL::text,'Kıvırcık saçları zıplayan kadın barda gülüyor.'::text),
(345510,38390,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... göndör haja ugrál, nevet a bárban.'::text,'akinek a'::text,'aki'::text,'ami'::text,'A nő, akinek a göndör haja ugrál, nevet a bárban.'::text),
(345513,38391,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie erzählte dem Barkeeper, dass ihre Haare seit ihrer Kindheit lockig ...'::text,'waren'::text,'sind'::text,'wurden'::text,'Sie erzählte dem Barkeeper, dass ihre Haare seit ihrer Kindheit lockig waren.'::text),
(345517,38391,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала барменові, що її волосся ... кучерявим з дитинства.'::text,'було'::text,'є'::text,'ставало'::text,'Вона сказала барменові, що її волосся було кучерявим з дитинства.'::text),
(345516,38391,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dijo al camarero que su pelo ... rizado desde que era niña.'::text,'había sido'::text,'ha sido'::text,'estaba siendo'::text,'Le dijo al camarero que su pelo había sido rizado desde que era niña.'::text),
(345515,38391,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit au barman que ses cheveux ... bouclés depuis qu''elle était petite.'::text,'étaient'::text,'sont'::text,'étaient en train d''être'::text,'Elle a dit au barman que ses cheveux étaient bouclés depuis qu''elle était petite.'::text),
(345518,38391,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barmene saçlarının çocukluğundan beri kıvırcık ... söyledi.'::text,'olduğunu'::text,'olduğunu'::text,'olmakta olduğunu'::text,'Barmene saçlarının çocukluğundan beri kıvırcık olduğunu söyledi.'::text),
(345519,38391,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta a pultosnak, hogy a haja gyerekkora óta ... göndör.'::text,''::text,NULL::text,'volt'::text,'Azt mondta a pultosnak, hogy a haja gyerekkora óta göndör.'::text),
(345522,38392,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Haare ... glatt, als sie ein Baby war, aber jetzt sind sie lockig.'::text,'waren früher'::text,'waren'::text,'waren es gewohnt'::text,'Ihre Haare waren früher glatt, als sie ein Baby war, aber jetzt sind sie lockig.'::text),
(345526,38392,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її волосся ... прямим, коли вона була немовлям, а тепер воно кучеряве.'::text,'раніше було'::text,'бувало'::text,'звикло бути'::text,'Її волосся раніше було прямим, коли вона була немовлям, а тепер воно кучеряве.'::text),
(345525,38392,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su pelo ... liso cuando era bebé, pero ahora es rizado.'::text,'solía ser'::text,'era'::text,'estaba acostumbrado a ser'::text,'Su pelo solía ser liso cuando era bebé, pero ahora es rizado.'::text),
(345524,38392,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses cheveux ... raides quand elle était bébé, mais maintenant ils sont bouclés.'::text,'étaient'::text,'étaient'::text,'avaient l''habitude d''être'::text,'Ses cheveux étaient raides quand elle était bébé, mais maintenant ils sont bouclés.'::text),
(345527,38392,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bebekken saçları düz ..., ama şimdi kıvırcık.'::text,'idi'::text,'olurdu'::text,'olmaya alışkındı'::text,'Bebekken saçları düz idi, ama şimdi kıvırcık.'::text),
(345528,38392,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A haja egyenes ..., amikor baba volt, de most göndör.'::text,'volt régen'::text,'volt'::text,'hozzá volt szokva'::text,'A haja egyenes volt régen, amikor baba volt, de most göndör.'::text),
(382791,42533,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nur ein kleines Aufwärmen, klar: Bis zum Ende des Songs wird jede Rüsche hundert Drehungen ...'::text,'gemacht haben'::text,'machen'::text,'am Machen sein'::text,'Nur ein kleines Aufwärmen, klar: Bis zum Ende des Songs wird jede Rüsche hundert Drehungen gemacht haben.'::text),
(382795,42533,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто невеличка розминка, звісно: до кінця пісні кожен волан ... сто обертів.'::text,'зробить'::text,'зробить'::text,'робитиме'::text,'Просто невеличка розминка, звісно: до кінця пісні кожен волан зробить сто обертів.'::text),
(382794,42533,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo un pequeño calentamiento, claro: al final de la canción, cada volante ... cien vueltas.'::text,'habrá dado'::text,'dará'::text,'estará dando'::text,'Solo un pequeño calentamiento, claro: al final de la canción, cada volante habrá dado cien vueltas.'::text),
(382793,42533,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Juste un petit échauffement, évidemment : d''ici la fin de la chanson, chaque volant ... cent tours.'::text,'aura fait'::text,'fera'::text,'sera en train de faire'::text,'Juste un petit échauffement, évidemment : d''ici la fin de la chanson, chaque volant aura fait cent tours.'::text),
(382796,42533,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sadece küçük bir ısınma tabii: şarkının sonunda her fırfır yüz tur ...'::text,'atmış olacak'::text,'atacak'::text,'atıyor olacak'::text,'Sadece küçük bir ısınma tabii: şarkının sonunda her fırfır yüz tur atmış olacak.'::text),
(382797,42533,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak egy kis bemelegítés, persze: a dal végére minden fodor ... száz pörgést.'::text,'megtesz'::text,'meg fog tenni'::text,'tenni fog'::text,'Csak egy kis bemelegítés, persze: a dal végére minden fodor megtesz száz pörgést.'::text),
(382800,42534,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn sie sich nicht gedreht hätte, ... die Rüsche nicht so ikonisch ausgesehen.'::text,'hätte'::text,'wird'::text,'hat'::text,'Bro, wenn sie sich nicht gedreht hätte, hätte die Rüsche nicht so ikonisch ausgesehen.'::text),
(382804,42534,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби вона не закрутилася, той волан ... так культово.'::text,'не виглядав би'::text,'не виглядатиме'::text,'не виглядав'::text,'Бро, якби вона не закрутилася, той волан не виглядав би так культово.'::text),
(382803,42534,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si no hubiera girado, ese volante ... tan icónico.'::text,'no habría quedado'::text,'no quedará'::text,'no quedó'::text,'Bro, si no hubiera girado, ese volante no habría quedado tan icónico.'::text),
(382802,42534,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si elle n''avait pas tourné, ce volant ... aussi iconique.'::text,'n''aurait pas eu l''air'::text,'n''aura pas l''air'::text,'n''a pas eu l''air'::text,'Frérot, si elle n''avait pas tourné, ce volant n''aurait pas eu l''air aussi iconique.'::text),
(382805,42534,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dönmeseydi o fırfır bu kadar efsane ...'::text,'görünmezdi'::text,'görünmeyecek'::text,'görünmedi'::text,'Kanka, dönmeseydi o fırfır bu kadar efsane görünmezdi.'::text),
(382806,42534,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nem pördült volna meg, az a fodor ... ilyen ikonikusan.'::text,'nem nézett volna ki'::text,'nem fog kinézni'::text,'nem nézett ki'::text,'Tesó, ha nem pördült volna meg, az a fodor nem nézett volna ki ilyen ikonikusan.'::text),
(382809,42535,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie hat zugegeben, jede Rüsche von Hand ..., ohne Witz.'::text,'genäht zu haben'::text,'zu nähen'::text,'nähte'::text,'Bro, sie hat zugegeben, jede Rüsche von Hand genäht zu haben, ohne Witz.'::text),
(382813,42535,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона зізналася, що ... кожен волан вручну, без брехні.'::text,'пошила'::text,'шити'::text,'пошила'::text,'Бро, вона зізналася, що пошила кожен волан вручну, без брехні.'::text),
(382812,42535,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, admitió ... cada volante a mano, en serio.'::text,'haber cosido'::text,'coser'::text,'cosió'::text,'Bro, admitió haber cosido cada volante a mano, en serio.'::text),
(382811,42535,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle a avoué ... chaque volant à la main, sans mentir.'::text,'avoir cousu'::text,'coudre'::text,'a cousu'::text,'Frérot, elle a avoué avoir cousu chaque volant à la main, sans mentir.'::text),
(382814,42535,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, her fırfırı elle ... itiraf etti, yemin ederim.'::text,'diktiğini'::text,'dikmeyi'::text,'dikti'::text,'Kanka, her fırfırı elle diktiğini itiraf etti, yemin ederim.'::text),
(382815,42535,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, bevallotta, hogy minden fodrot kézzel ..., komolyan.'::text,'megvarrt'::text,'varrni'::text,'varrta'::text,'Tesó, bevallotta, hogy minden fodrot kézzel megvarrt, komolyan.'::text),
(382818,42536,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese 200 Rüschen ... viel gekostet haben; das Kostümbudget hat sich verdoppelt.'::text,'müssen'::text,'sollten'::text,'können nicht'::text,'Diese 200 Rüschen müssen viel gekostet haben; das Kostümbudget hat sich verdoppelt.'::text),
(382822,42536,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці 200 воланів ... коштувати чимало: бюджет на костюми подвоївся.'::text,'мусили'::text,'мали б'::text,'не могли'::text,'Ці 200 воланів мусили коштувати чимало: бюджет на костюми подвоївся.'::text),
(382821,42536,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esos 200 volantes ... mucho; el presupuesto de vestuario se duplicó.'::text,'debieron de costar'::text,'deberían haber costado'::text,'no pueden haber costado'::text,'Esos 200 volantes debieron de costar mucho; el presupuesto de vestuario se duplicó.'::text),
(382820,42536,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces 200 volants ... cher ; le budget costumes a doublé.'::text,'ont dû coûter'::text,'auraient dû coûter'::text,'ne peuvent pas avoir coûté'::text,'Ces 200 volants ont dû coûter cher ; le budget costumes a doublé.'::text),
(382823,42536,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O 200 fırfır çok pahalıya ...; kostüm bütçesi ikiye katlandı.'::text,'mal olmuş olmalı'::text,'mal olmalıydı'::text,'mal olmuş olamaz'::text,'O 200 fırfır çok pahalıya mal olmuş olmalı; kostüm bütçesi ikiye katlandı.'::text),
(382824,42536,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a 200 fodor ...; a jelmezköltségvetés megduplázódott.'::text,'biztosan sokba került'::text,'sokba kellett volna kerülnie'::text,'nem kerülhetett sokba'::text,'Az a 200 fodor biztosan sokba került; a jelmezköltségvetés megduplázódott.'::text),
(382827,42537,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ließ jede Rüsche vor der Show von einer Schneiderin ...'::text,'nähen'::text,'nähen'::text,'nähend'::text,'Sie ließ jede Rüsche vor der Show von einer Schneiderin nähen.'::text),
(382831,42537,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перед виступом вона віддала кожен волан кравчині, щоб та його ...'::text,'пошила'::text,'шила'::text,'шиття'::text,'Перед виступом вона віддала кожен волан кравчині, щоб та його пошила.'::text),
(382830,42537,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes del espectáculo, mandó ... cada volante a una modista.'::text,'coser'::text,'coser'::text,'cosiendo'::text,'Antes del espectáculo, mandó coser cada volante a una modista.'::text),
(382829,42537,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant le spectacle, elle a fait ... chaque volant par une couturière.'::text,'coudre'::text,'coudre'::text,'cousant'::text,'Avant le spectacle, elle a fait coudre chaque volant par une couturière.'::text),
(382832,42537,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gösteriden önce her fırfırı bir terziye ...'::text,'diktirdi'::text,'dikti'::text,'dikerek'::text,'Gösteriden önce her fırfırı bir terziye diktirdi.'::text),
(382833,42537,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az előadás előtt minden fodrot ... egy varrónővel.'::text,'megvarratott'::text,'varratott'::text,'varrva'::text,'Az előadás előtt minden fodrot megvarratott egy varrónővel.'::text),
(382836,42538,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswerterweise wünschen sich viele Beobachter, sie ... einen Rock mit so vielen Rüschen.'::text,'hätten'::text,'haben'::text,'werden haben'::text,'Bemerkenswerterweise wünschen sich viele Beobachter, sie hätten einen Rock mit so vielen Rüschen.'::text),
(382840,42538,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дивно, але багато спостерігачів хотіли б, щоб у них ... спідниця з такою кількістю воланів.'::text,'була'::text,'є'::text,'буде'::text,'Дивно, але багато спостерігачів хотіли б, щоб у них була спідниця з такою кількістю воланів.'::text),
(382839,42538,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Curiosamente, muchos observadores desearían ... una falda con tantos volantes.'::text,'tener'::text,'tener'::text,'tener'::text,'Curiosamente, muchos observadores desearían tener una falda con tantos volantes.'::text),
(382838,42538,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait remarquable, beaucoup d''observateurs aimeraient ... une jupe avec autant de volants.'::text,'avoir'::text,'avoir'::text,'avoir'::text,'Fait remarquable, beaucoup d''observateurs aimeraient avoir une jupe avec autant de volants.'::text),
(382841,42538,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat çekici biçimde, birçok gözlemci keşke bu kadar fırfırlı bir etekleri ... diyor.'::text,'olsa'::text,'var'::text,'olacak'::text,'Dikkat çekici biçimde, birçok gözlemci keşke bu kadar fırfırlı bir etekleri olsa diyor.'::text),
(382842,42538,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó, hogy sok megfigyelő szeretné, ha nekik is ... egy ennyi fodros szoknyájuk.'::text,'lenne'::text,'van'::text,'lesz'::text,'Figyelemre méltó, hogy sok megfigyelő szeretné, ha nekik is lenne egy ennyi fodros szoknyájuk.'::text),
(382845,42539,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kleid, ... Rüschen rot und schwarz sind, wirbelt um ihre Beine.'::text,'dessen'::text,'das'::text,'welches'::text,'Das Kleid, dessen Rüschen rot und schwarz sind, wirbelt um ihre Beine.'::text),
(382849,42539,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сукня, ... волани червоні й чорні, кружляє навколо її ніг.'::text,'чиї'::text,'яка'::text,'що'::text,'Сукня, чиї волани червоні й чорні, кружляє навколо її ніг.'::text),
(382848,42539,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vestido, ... volantes son rojos y negros, gira alrededor de sus piernas.'::text,'cuyos'::text,'el cual'::text,'que'::text,'El vestido, cuyos volantes son rojos y negros, gira alrededor de sus piernas.'::text),
(382847,42539,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La robe, ... les volants sont rouges et noirs, tourbillonne autour de ses jambes.'::text,'dont'::text,'qui'::text,'que'::text,'La robe, dont les volants sont rouges et noirs, tourbillonne autour de ses jambes.'::text),
(382850,42539,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fırfırları kırmızı ve siyah olan elbise ... bacaklarının etrafında dönüyor.'::text,''::text,NULL::text,NULL::text,'Fırfırları kırmızı ve siyah olan elbise bacaklarının etrafında dönüyor.'::text),
(382851,42539,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ruha, ... fodrai pirosak és feketék, a lába körül kavarog.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A ruha, amelynek a fodrai pirosak és feketék, a lába körül kavarog.'::text),
(382854,42540,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Rock hat auf jeder Stufe ...'::text,'eine breite Rüsche'::text,'die breite Rüsche'::text,'breite Rüsche'::text,'Ihr Rock hat auf jeder Stufe eine breite Rüsche.'::text),
(382858,42540,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її спідниця має ... на кожному ярусі.'::text,'широкий волан'::text,'широкий волан'::text,'широкий волан'::text,'Її спідниця має широкий волан на кожному ярусі.'::text),
(382857,42540,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su falda tiene ... en cada nivel.'::text,'un volante ancho'::text,'el volante ancho'::text,'volante ancho'::text,'Su falda tiene un volante ancho en cada nivel.'::text),
(382856,42540,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa jupe a ... à chaque étage.'::text,'un large volant'::text,'le large volant'::text,'large volant'::text,'Sa jupe a un large volant à chaque étage.'::text),
(382859,42540,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eteğinin her katında ... var.'::text,'geniş bir fırfır'::text,'geniş fırfır'::text,'geniş fırfır'::text,'Eteğinin her katında geniş bir fırfır var.'::text),
(382860,42540,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szoknyáján minden rétegen ... van.'::text,'egy széles fodor'::text,'a széles fodor'::text,'széles fodor'::text,'A szoknyáján minden rétegen egy széles fodor van.'::text),
(382863,42541,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Rüschen wirbelten noch einen Moment weiter, ... sie schon stehen geblieben war.'::text,'obwohl'::text,'trotz'::text,'wegen'::text,'Die Rüschen wirbelten noch einen Moment weiter, obwohl sie schon stehen geblieben war.'::text),
(382867,42541,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Волани ще якусь мить кружляли, ... вона вже зупинилася.'::text,'хоча'::text,'попри'::text,'завдяки'::text,'Волани ще якусь мить кружляли, хоча вона вже зупинилася.'::text),
(382866,42541,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los volantes siguieron girando un momento, ... ella ya se había detenido.'::text,'aunque'::text,'a pesar de'::text,'debido a'::text,'Los volantes siguieron girando un momento, aunque ella ya se había detenido.'::text),
(382865,42541,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les volants ont continué à tourbillonner un instant, ... elle s''était déjà arrêtée.'::text,'même si'::text,'malgré'::text,'grâce à'::text,'Les volants ont continué à tourbillonner un instant, même si elle s''était déjà arrêtée.'::text),
(382868,42541,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fırfırlar bir süre daha dönmeye devam etti, ... o çoktan durmuştu.'::text,'gerçi'::text,'rağmen'::text,'sayesinde'::text,'Fırfırlar bir süre daha dönmeye devam etti, gerçi o çoktan durmuştu.'::text),
(382869,42541,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fodrok még egy pillanatig tovább kavarogtak, ... ő már megállt.'::text,'pedig'::text,'ellenére'::text,'miatt'::text,'A fodrok még egy pillanatig tovább kavarogtak, pedig ő már megállt.'::text),
(346413,38491,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Spezialistin beginnt typischerweise damit, das Wirbelsäulenmodell ...'::text,'vorzuführen'::text,'vorzuführen'::text,'vorführen'::text,'Die Spezialistin beginnt typischerweise damit, das Wirbelsäulenmodell vorzuführen.'::text),
(346417,38491,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фахівчиня зазвичай починає з того, що ... модель хребта.'::text,'показує'::text,'показує'::text,'показує'::text,'Фахівчиня зазвичай починає з того, що показує модель хребта.'::text),
(346416,38491,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La especialista suele empezar ... el modelo de la columna.'::text,'enseñando'::text,'por enseñar'::text,'enseñar'::text,'La especialista suele empezar enseñando el modelo de la columna.'::text),
(346415,38491,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La spécialiste commence généralement par ... le modèle de colonne vertébrale.'::text,'montrer'::text,'montrer'::text,'montrer'::text,'La spécialiste commence généralement par montrer le modèle de colonne vertébrale.'::text),
(346418,38491,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uzman genellikle omurga modelini ... başlar.'::text,'göstererek'::text,'göstermeye'::text,'göstermek'::text,'Uzman genellikle omurga modelini göstererek başlar.'::text),
(346419,38491,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szakember jellemzően azzal kezdi, hogy ... a gerincmodellt.'::text,'bemutatja'::text,'bemutatja'::text,'bemutatja'::text,'A szakember jellemzően azzal kezdi, hogy bemutatja a gerincmodellt.'::text),
(346422,38492,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie führt die Wirbelsäule so ernst vor! Sein Rücken wird nie wieder derselbe sein, ...?'::text,'oder'::text,'nicht wahr'::text,'ja'::text,'Sie führt die Wirbelsäule so ernst vor! Sein Rücken wird nie wieder derselbe sein, oder?'::text),
(346426,38492,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона показує хребет так серйозно! Його спина вже ніколи не буде такою, як раніше, ...?'::text,'правда'::text,'чи не так'::text,'так'::text,'Вона показує хребет так серйозно! Його спина вже ніколи не буде такою, як раніше, правда?'::text),
(346425,38492,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Enseña la columna con tanta seriedad! Su espalda nunca volverá a ser la misma, ¿...?'::text,'verdad'::text,'no'::text,'sí'::text,'¡Enseña la columna con tanta seriedad! Su espalda nunca volverá a ser la misma, ¿verdad?'::text),
(346424,38492,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle montre la colonne tellement sérieusement ! Son dos ne sera plus jamais le même, ... ?'::text,'hein'::text,'n''est-ce pas'::text,'non'::text,'Elle montre la colonne tellement sérieusement ! Son dos ne sera plus jamais le même, hein ?'::text),
(346427,38492,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omurgayı öyle ciddi gösteriyor ki! Sırtı bir daha asla eskisi gibi olmayacak, ...?'::text,'değil mi'::text,'değil mi'::text,'öyle mi'::text,'Omurgayı öyle ciddi gösteriyor ki! Sırtı bir daha asla eskisi gibi olmayacak, değil mi?'::text),
(346428,38492,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan komolyan mutatja be a gerincet! A háta soha többé nem lesz a régi, ...?'::text,'ugye'::text,'igaz'::text,'nem'::text,'Olyan komolyan mutatja be a gerincet! A háta soha többé nem lesz a régi, ugye?'::text),
(346440,38494,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das Wirbelsäulenmodell eine Stunde lang vorgeführt, bevor er es endlich verstand. Was für ein Albtraum!'::text,'hatte'::text,'hat'::text,'hatte gerade'::text,'Sie hatte das Wirbelsäulenmodell eine Stunde lang vorgeführt, bevor er es endlich verstand. Was für ein Albtraum!'::text),
(346444,38494,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... модель хребта цілу годину, перш ніж він нарешті зрозумів. Який жах!'::text,'показувала'::text,'показує'::text,'показувала'::text,'Вона показувала модель хребта цілу годину, перш ніж він нарешті зрозумів. Який жах!'::text),
(346443,38494,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el modelo de la columna durante una hora antes de que él por fin lo entendiera. ¡Qué pesadilla!'::text,'Había estado enseñando'::text,'Ha estado enseñando'::text,'Estaba enseñando'::text,'Había estado enseñando el modelo de la columna durante una hora antes de que él por fin lo entendiera. ¡Qué pesadilla!'::text),
(346442,38494,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le modèle de colonne pendant une heure avant qu''il finisse par comprendre. Quel cauchemar !'::text,'avait montré'::text,'a montré'::text,'montrait'::text,'Elle avait montré le modèle de colonne pendant une heure avant qu''il finisse par comprendre. Quel cauchemar !'::text),
(346445,38494,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sonunda anlayana kadar bir saat boyunca ... omurga modelini. Ne kâbus!'::text,'gösterip durmuştu'::text,'gösterip duruyor'::text,'gösteriyordu'::text,'O sonunda anlayana kadar bir saat boyunca gösterip durmuştu omurga modelini. Ne kâbus!'::text),
(346446,38494,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órán át ... a gerincmodellt, mire a fiú végre megértette. Micsoda rémálom!'::text,'mutogatta'::text,'mutogatja'::text,'mutogatta'::text,'Egy órán át mutogatta a gerincmodellt, mire a fiú végre megértette. Micsoda rémálom!'::text),
(346449,38495,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Sitzung wird sie ihm jede Dehnübung ...'::text,'vorgeführt haben'::text,'vorführen'::text,'vorführen'::text,'Bis zum Ende der Sitzung wird sie ihm jede Dehnübung vorgeführt haben.'::text),
(346453,38495,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця сеансу вона ... йому кожну вправу на розтяжку.'::text,'покаже'::text,'покаже'::text,'показуватиме'::text,'До кінця сеансу вона покаже йому кожну вправу на розтяжку.'::text),
