(390812,43424,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il goûte encore cette soupe, il la ... encore.'::text,'recrachera'::text,'recracherait'::text,'recracha'::text,'S''il goûte encore cette soupe, il la recrachera encore.'::text),
(390815,43424,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çorbayı bir daha tadarsa yine ...'::text,'tükürecek'::text,'tükürürdü'::text,'tükürdü'::text,'O çorbayı bir daha tadarsa yine tükürecek.'::text),
(390816,43424,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha újra megkóstolja azt a levest, megint ...'::text,'ki fogja köpni'::text,'kiköpné'::text,'kiköpte'::text,'Ha újra megkóstolja azt a levest, megint ki fogja köpni.'::text),
(390819,43425,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Suppe 50 Euro kosten würde, ... er sie vor dem Kunden nicht aus.'::text,'spuckte'::text,'spuckt'::text,'spuckt'::text,'Wenn die Suppe 50 Euro kosten würde, spuckte er sie vor dem Kunden nicht aus.'::text),
(390823,43425,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби суп коштував 50 євро, він не ... його перед клієнтом.'::text,'виплюнув би'::text,'виплюне'::text,'випльовує'::text,'Якби суп коштував 50 євро, він не виплюнув би його перед клієнтом.'::text),
(390822,43425,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la sopa costara 50 euros, no la ... delante del cliente.'::text,'escupiría'::text,'escupirá'::text,'escupe'::text,'Si la sopa costara 50 euros, no la escupiría delante del cliente.'::text),
(390821,43425,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la soupe coûtait 50 euros, il ne la ... pas devant le client.'::text,'recracherait'::text,'recrachera'::text,'recrache'::text,'Si la soupe coûtait 50 euros, il ne la recracherait pas devant le client.'::text),
(390824,43425,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çorba 50 avro olsaydı, müşterinin önünde ...'::text,'tükürmezdi'::text,'tükürmeyecek'::text,'tükürmüyor'::text,'Çorba 50 avro olsaydı, müşterinin önünde tükürmezdi.'::text),
(390825,43425,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a leves 50 euróba kerülne, ... az ügyfél előtt.'::text,'nem köpné ki'::text,'nem fogja kiköpni'::text,'nem köpi ki'::text,'Ha a leves 50 euróba kerülne, nem köpné ki az ügyfél előtt.'::text),
(390828,43426,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Suppe ... ausgespuckt, und deshalb ist sie nicht mehr in seinem Mund.'::text,'wurde'::text,'hat'::text,'wird'::text,'Die Suppe wurde ausgespuckt, und deshalb ist sie nicht mehr in seinem Mund.'::text),
(390832,43426,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суп ..., і саме тому його більше немає в роті.'::text,'був виплюнутий'::text,'виплюнув'::text,'випльовується'::text,'Суп був виплюнутий, і саме тому його більше немає в роті.'::text),
(390831,43426,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sopa ..., y por eso ya no está en su boca.'::text,'fue escupida'::text,'escupió'::text,'es escupida'::text,'La sopa fue escupida, y por eso ya no está en su boca.'::text),
(390830,43426,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La soupe ..., et c''est pour ça qu''elle n''est plus dans sa bouche.'::text,'a été recrachée'::text,'a recraché'::text,'est recrachée'::text,'La soupe a été recrachée, et c''est pour ça qu''elle n''est plus dans sa bouche.'::text),
(390833,43426,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çorba ..., o yüzden artık ağzında değil.'::text,'tükürüldü'::text,'tükürdü'::text,'tükürülür'::text,'Çorba tükürüldü, o yüzden artık ağzında değil.'::text),
(390834,43426,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A leves ..., és ezért nincs már a szájában.'::text,'ki lett köpve'::text,'kiköpött'::text,'ki van köpve'::text,'A leves ki lett köpve, és ezért nincs már a szájában.'::text),
(390846,43428,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, wie du die Suppe ausgespuckt hast; sie ... furchtbar schmecken.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Respekt, wie du die Suppe ausgespuckt hast; sie muss furchtbar schmecken.'::text),
(390850,43428,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, як ти виплюнув той суп; він ... бути жахливим на смак.'::text,'мусить'::text,'не може'::text,'мав би'::text,'Респект, як ти виплюнув той суп; він мусить бути жахливим на смак.'::text),
(390849,43428,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto por cómo escupiste esa sopa; ... saber fatal.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Respeto por cómo escupiste esa sopa; debe de saber fatal.'::text),
(390848,43428,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect pour la façon dont tu as recraché cette soupe ; elle ... avoir un goût horrible.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Respect pour la façon dont tu as recraché cette soupe ; elle doit avoir un goût horrible.'::text),
(390851,43428,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çorbayı tükürüşüne saygı; tadı berbat ...'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'O çorbayı tükürüşüne saygı; tadı berbat olmalı.'::text),
(390852,43428,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, ahogy kiköpted azt a levest; az ízének ... borzalmasnak lennie.'::text,'kell'::text,'nem lehet'::text,'kellene'::text,'Respekt, ahogy kiköpted azt a levest; az ízének kell borzalmasnak lennie.'::text),
(390855,43429,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, aber die Suppe, ... du ausgespuckt hast, sah irgendwie verdächtig aus.'::text,'die'::text,'wer'::text,'wo'::text,'Respekt, aber die Suppe, die du ausgespuckt hast, sah irgendwie verdächtig aus.'::text),
(390859,43429,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, але суп, ... ти виплюнув, виглядав якось підозріло.'::text,'який'::text,'хто'::text,'де'::text,'Респект, але суп, який ти виплюнув, виглядав якось підозріло.'::text),
(390858,43429,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, pero la sopa ... escupiste parecía algo sospechosa.'::text,'que'::text,'quien'::text,'donde'::text,'Respeto, pero la sopa que escupiste parecía algo sospechosa.'::text),
(390857,43429,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, mais la soupe ... tu as recrachée avait l''air un peu louche.'::text,'que'::text,'qui'::text,'où'::text,'Respect, mais la soupe que tu as recrachée avait l''air un peu louche.'::text),
(390860,43429,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygı, ama tükürdüğün çorba ... biraz şüpheli görünüyordu.'::text,''::text,NULL::text,NULL::text,'Saygı, ama tükürdüğün çorba biraz şüpheli görünüyordu.'::text),
(390861,43429,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, de a leves, ... kiköptél, elég gyanúsan nézett ki.'::text,'amit'::text,'aki'::text,'ahol'::text,'Respekt, de a leves, amit kiköptél, elég gyanúsan nézett ki.'::text),
(390864,43430,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast gesagt, du ... sie nicht ausspucken, und dann hast du es getan. Respekt.'::text,'würdest'::text,'wirst'::text,NULL::text,'Ehrlich, du hast gesagt, du würdest sie nicht ausspucken, und dann hast du es getan. Respekt.'::text),
(390868,43430,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти казав, що ... його, а потім таки виплюнув. Респект.'::text,'не виплюнеш'::text,'не виплюнеш'::text,'не випльовуєш'::text,'Чесно, ти казав, що не виплюнеш його, а потім таки виплюнув. Респект.'::text),
(390867,43430,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, dijiste que no la ..., y luego lo hiciste. Respeto.'::text,'escupirías'::text,'escupirás'::text,'escupes'::text,'Sinceramente, dijiste que no la escupirías, y luego lo hiciste. Respeto.'::text),
(390866,43430,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as dit que tu ne la ... pas, et puis tu l''as fait. Respect.'::text,'recracherais'::text,'recracheras'::text,'recraches'::text,'Franchement, tu as dit que tu ne la recracherais pas, et puis tu l''as fait. Respect.'::text),
(390869,43430,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası onu ... söyledin, sonra da tükürdün. Saygı.'::text,'tükürmeyeceğini'::text,'tükürmeyeceğini'::text,'tükürmediğini'::text,'Açıkçası onu tükürmeyeceğini söyledin, sonra da tükürdün. Saygı.'::text),
(390870,43430,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, azt mondtad, hogy ..., aztán mégis kiköpted. Respekt.'::text,'nem köpöd ki'::text,'nem fogod kiköpni'::text,'nem köpöd ki'::text,'Őszintén, azt mondtad, hogy nem köpöd ki, aztán mégis kiköpted. Respekt.'::text),
(390972,43442,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie den Einkauf ins Haus ..., hielt ihr Mann den anderen Henkel der Tasche.'::text,'trug'::text,'trug'::text,'getragen hat'::text,'Während sie den Einkauf ins Haus trug, hielt ihr Mann den anderen Henkel der Tasche.'::text),
(390976,43442,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... покупки в дім, її чоловік тримав другу ручку пакета.'::text,'несла'::text,'занесла'::text,'занесла'::text,'Поки вона несла покупки в дім, її чоловік тримав другу ручку пакета.'::text),
(390975,43442,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ella ... la compra, su marido sujetaba la otra asa de la bolsa.'::text,'metía'::text,'metió'::text,'ha metido'::text,'Mientras ella metía la compra, su marido sujetaba la otra asa de la bolsa.'::text),
(390974,43442,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... les courses à l''intérieur, son mari tenait l''autre anse du sac.'::text,'portait'::text,'porta'::text,'a porté'::text,'Pendant qu''elle portait les courses à l''intérieur, son mari tenait l''autre anse du sac.'::text),
(390977,43442,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O alışverişi içeri ..., eşi poşetin diğer sapını tutuyordu.'::text,'taşırken'::text,'taşıdı'::text,'taşımış'::text,'O alışverişi içeri taşırken, eşi poşetin diğer sapını tutuyordu.'::text),
(390978,43442,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ... a bevásárlást, a férje a szatyor másik fülét fogta.'::text,'hozta be'::text,'behozta'::text,'behozta már'::text,'Miközben ő hozta be a bevásárlást, a férje a szatyor másik fülét fogta.'::text),
(390981,43443,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie und ihr Mann ... schon seit einer halben Stunde an der Küchentheke Papiere.'::text,'unterschreiben'::text,'unterschreiben gerade'::text,'unterschreiben'::text,'Sie und ihr Mann unterschreiben schon seit einer halben Stunde an der Küchentheke Papiere.'::text),
(390985,43443,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона і її чоловік уже пів години ... папери біля стільниці.'::text,'підписують'::text,'підписують'::text,'підписують'::text,'Вона і її чоловік уже пів години підписують папери біля стільниці.'::text),
(390984,43443,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella y su marido ... papeles en la encimera desde hace media hora.'::text,'están firmando'::text,'están firmando'::text,'firman'::text,'Ella y su marido están firmando papeles en la encimera desde hace media hora.'::text),
(390983,43443,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle et son mari ... des papiers au comptoir depuis une demi-heure.'::text,'signent'::text,'sont en train de signer'::text,'signent'::text,'Elle et son mari signent des papiers au comptoir depuis une demi-heure.'::text),
(390986,43443,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ve eşi yarım saattir tezgâhta evrak ...'::text,'imzalıyor'::text,'imzalıyor'::text,'imzalar'::text,'O ve eşi yarım saattir tezgâhta evrak imzalıyor.'::text),
(390987,43443,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő és a férje már fél órája ... a papírokat a pultnál.'::text,'írják alá'::text,'írják alá'::text,'aláírják'::text,'Ő és a férje már fél órája írják alá a papírokat a pultnál.'::text),
(390990,43444,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade die Dokumente, als der Stift ihres Mannes den Geist aufgab! Eine totale Katastrophe!'::text,'unterschrieben'::text,'unterschrieben'::text,'unterschreiben'::text,'Sie unterschrieben gerade die Dokumente, als der Stift ihres Mannes den Geist aufgab! Eine totale Katastrophe!'::text),
(390994,43444,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... документи, коли в її чоловіка закінчилася ручка! Повна катастрофа!'::text,'підписували'::text,'підписали'::text,'підписують'::text,'Вони підписували документи, коли в її чоловіка закінчилася ручка! Повна катастрофа!'::text),
(390993,43444,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... los documentos cuando el boli de su marido se murió! ¡Un desastre total!'::text,'Estaban firmando'::text,'Firmaron'::text,'Están firmando'::text,'¡Estaban firmando los documentos cuando el boli de su marido se murió! ¡Un desastre total!'::text),
(390992,43444,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... les documents quand le stylo de son mari a lâché ! Une catastrophe totale !'::text,'signaient'::text,'ont signé'::text,'signent'::text,'Ils signaient les documents quand le stylo de son mari a lâché ! Une catastrophe totale !'::text),
(390995,43444,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eşinin kalemi bittiğinde belgeleri ...! Tam bir felaket!'::text,'imzalıyorlardı'::text,'imzaladılar'::text,'imzalıyorlar'::text,'Eşinin kalemi bittiğinde belgeleri imzalıyorlardı! Tam bir felaket!'::text),
(390996,43444,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a dokumentumokat, amikor a férje tolla bemondta az unalmast! Totális katasztrófa!'::text,'írták alá'::text,'aláírták'::text,'aláírják'::text,'Épp írták alá a dokumentumokat, amikor a férje tolla bemondta az unalmast! Totális katasztrófa!'::text),
(390999,43445,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Mann ... vier Dokumente unterschrieben, und sie hat keins unterschrieben! Das absolute Ende!'::text,'hat'::text,'hat'::text,'unterschreibt'::text,'Ihr Mann hat vier Dokumente unterschrieben, und sie hat keins unterschrieben! Das absolute Ende!'::text),
(391003,43445,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її чоловік ... чотири документи, а вона — жодного! Кінець світу!'::text,'підписав'::text,'підписує'::text,'підписує'::text,'Її чоловік підписав чотири документи, а вона — жодного! Кінець світу!'::text),
(391002,43445,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su marido ... cuatro documentos y ella no ha firmado ninguno! ¡El fin del mundo!'::text,'ha firmado'::text,'ha estado firmando'::text,'firma'::text,'¡Su marido ha firmado cuatro documentos y ella no ha firmado ninguno! ¡El fin del mundo!'::text),
(391001,43445,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son mari ... quatre documents, et elle n''en a signé aucun ! La fin absolue !'::text,'a signé'::text,'est en train de signer'::text,'signe'::text,'Son mari a signé quatre documents, et elle n''en a signé aucun ! La fin absolue !'::text),
(391004,43445,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eşi dört belge ..., o ise hiçbirini imzalamadı! Resmen kıyamet!'::text,'imzaladı'::text,'imzalıyor'::text,'imzalar'::text,'Eşi dört belge imzaladı, o ise hiçbirini imzalamadı! Resmen kıyamet!'::text),
(391005,43445,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férje már ... négy dokumentumot, ő meg egyet sem! Totál világvége!'::text,'aláírt'::text,'írogat'::text,'aláír'::text,'A férje már aláírt négy dokumentumot, ő meg egyet sem! Totál világvége!'::text),
(391008,43446,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie einen Stift gefunden hatte, ... ihr Mann schon jede Seite unterschrieben! Verrat!'::text,'hatte'::text,'hat'::text,'unterschreibt'::text,'Als sie einen Stift gefunden hatte, hatte ihr Mann schon jede Seite unterschrieben! Verrat!'::text),
(391012,43446,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона знайшла ручку, її чоловік уже ... кожну сторінку! Зрада!'::text,'підписав'::text,'підписав'::text,'підписує'::text,'Поки вона знайшла ручку, її чоловік уже підписав кожну сторінку! Зрада!'::text),
(391011,43446,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando encontró un boli, su marido ya ... todas las páginas! ¡Traición!'::text,'había firmado'::text,'ha firmado'::text,'firma'::text,'¡Para cuando encontró un boli, su marido ya había firmado todas las páginas! ¡Traición!'::text),
(391010,43446,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps qu''elle trouve un stylo, son mari ... chaque page ! Trahison !'::text,'avait signé'::text,'a signé'::text,'signe'::text,'Le temps qu''elle trouve un stylo, son mari avait signé chaque page ! Trahison !'::text),
(391013,43446,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bir kalem bulana kadar eşi her sayfayı çoktan ...! İhanet!'::text,'imzalamıştı'::text,'imzaladı'::text,'imzalıyor'::text,'O bir kalem bulana kadar eşi her sayfayı çoktan imzalamıştı! İhanet!'::text),
(391014,43446,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire tollat talált, a férje már ... minden oldalt! Árulás!'::text,'aláírta'::text,'aláírta'::text,'aláírja'::text,'Mire tollat talált, a férje már aláírta minden oldalt! Árulás!'::text),
(391017,43447,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich hab gehört, dass sie und ihr Mann heute Abend um sechs den Einkauf nach Hause ...'::text,'tragen werden'::text,'tragen werden'::text,'tragen'::text,'Rate mal, ich hab gehört, dass sie und ihr Mann heute Abend um sechs den Einkauf nach Hause tragen werden.'::text),
(391021,43447,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, я чула, що сьогодні о шостій вона і її чоловік ... покупки додому.'::text,'нестимуть'::text,'донесуть'::text,'несуть'::text,'Уяви, я чула, що сьогодні о шостій вона і її чоловік нестимуть покупки додому.'::text),
(391020,43447,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? He oído que esta noche a las seis ella y su marido ... la compra a casa.'::text,'estarán llevando'::text,'llevarán'::text,'llevan'::text,'¿Sabes qué? He oído que esta noche a las seis ella y su marido estarán llevando la compra a casa.'::text),
(391019,43447,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, j''ai entendu dire que ce soir à six heures, elle et son mari ... les courses à la maison.'::text,'seront en train de rapporter'::text,'rapporteront'::text,'rapportent'::text,'Devine quoi, j''ai entendu dire que ce soir à six heures, elle et son mari seront en train de rapporter les courses à la maison.'::text),
(391022,43447,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, duydum ki bu akşam saat altıda o ve eşi alışverişi eve ...'::text,'taşıyor olacaklar'::text,'taşıyacaklar'::text,'taşıyorlar'::text,'Bil bakalım, duydum ki bu akşam saat altıda o ve eşi alışverişi eve taşıyor olacaklar.'::text),
(391023,43447,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy ma este hatkor ő és a férje épp ... haza a bevásárlást.'::text,'viszik'::text,'fogják vinni'::text,'viszik'::text,'Képzeld, azt hallottam, hogy ma este hatkor ő és a férje épp viszik haza a bevásárlást.'::text),
(391026,43448,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, wie er seiner Frau versprochen hat: „Ich ... nächstes Mal den ganzen Einkauf.“'::text,'trage'::text,'trage'::text,'trage gerade'::text,'Bestie, ich hab gehört, wie er seiner Frau versprochen hat: „Ich trage nächstes Mal den ganzen Einkauf.“'::text),
(391030,43448,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, як він пообіцяв дружині: «Я ... наступного разу всі покупки».'::text,'понесу'::text,'нестиму'::text,'несу'::text,'Подруго, я чула, як він пообіцяв дружині: «Я понесу наступного разу всі покупки».'::text),
(391029,43448,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, le oí prometer a su mujer: «Yo ... toda la compra la próxima vez».'::text,'llevaré'::text,'estaré llevando'::text,'llevo'::text,'Amiga, le oí prometer a su mujer: «Yo llevaré toda la compra la próxima vez».'::text),
(391028,43448,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma bestie, je l''ai entendu promettre à sa femme : « Je ... toutes les courses la prochaine fois. »'::text,'porterai'::text,'serai en train de porter'::text,'porte'::text,'Ma bestie, je l''ai entendu promettre à sa femme : « Je porterai toutes les courses la prochaine fois. »'::text),
(391031,43448,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eşine “Bir dahaki sefere bütün alışverişi ben ...” diye söz verdiğini duydum.'::text,'taşıyacağım'::text,'taşıyor olacağım'::text,'taşıyorum'::text,'Kanka, eşine “Bir dahaki sefere bütün alışverişi ben taşıyacağım” diye söz verdiğini duydum.'::text),
(391032,43448,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, hallottam, ahogy megígérte a feleségének: „Legközelebb én ... az egész bevásárlást.”'::text,'cipelem'::text,'fogom cipelni'::text,'cipelem'::text,'Csajszi, hallottam, ahogy megígérte a feleségének: „Legközelebb én cipelem az egész bevásárlást.”'::text),
(391035,43449,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unter uns, er behauptet, seine Frau ... vor der Hochzeit jede Woche die Taschen allein getragen.'::text,'habe'::text,'habe früher'::text,'sei es gewohnt gewesen'::text,'Unter uns, er behauptet, seine Frau habe vor der Hochzeit jede Woche die Taschen allein getragen.'::text),
(391039,43449,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Між нами, він стверджує, що його дружина ... сумки сама щотижня до весілля.'::text,'носила'::text,'носила'::text,'звикла носити'::text,'Між нами, він стверджує, що його дружина носила сумки сама щотижня до весілля.'::text),
(391038,43449,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nosotros, dice que su mujer ... las bolsas sola cada semana antes de la boda.'::text,'llevaba'::text,'solía llevar'::text,'estaba acostumbrada a llevar'::text,'Entre nosotros, dice que su mujer llevaba las bolsas sola cada semana antes de la boda.'::text),
(391037,43449,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nous, il prétend que sa femme ... les sacs seule chaque semaine avant le mariage.'::text,'portait'::text,'portait'::text,'avait l''habitude de porter'::text,'Entre nous, il prétend que sa femme portait les sacs seule chaque semaine avant le mariage.'::text),
(391040,43449,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aramızda kalsın, düğünden önce karısının her hafta poşetleri tek başına ... iddia ediyor.'::text,'taşıdığını'::text,'taşıdığını'::text,'taşımaya alışkın olduğunu'::text,'Aramızda kalsın, düğünden önce karısının her hafta poşetleri tek başına taşıdığını iddia ediyor.'::text),
(391041,43449,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maradjon köztünk, azt állítja, hogy a felesége az esküvő előtt minden héten egyedül ... a szatyrokat.'::text,'cipelte'::text,'cipelte'::text,'hozzá volt szokva, hogy cipelje'::text,'Maradjon köztünk, azt állítja, hogy a felesége az esküvő előtt minden héten egyedül cipelte a szatyrokat.'::text),
(391062,43452,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... fünf Jahre verheiratet, als sie diese Dokumente zusammen unterschrieben.'::text,'waren schon'::text,'sind'::text,'waren'::text,'Sie waren schon fünf Jahre verheiratet, als sie diese Dokumente zusammen unterschrieben.'::text),
(391066,43452,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... одружені п''ять років, коли разом підписали ці документи.'::text,'були вже'::text,'є'::text,'були'::text,'Вони були вже одружені п''ять років, коли разом підписали ці документи.'::text),
(391065,43452,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cinco años casados cuando firmaron juntos estos documentos.'::text,'Llevaban'::text,'Llevan'::text,'Estuvieron'::text,'Llevaban cinco años casados cuando firmaron juntos estos documentos.'::text),
(391064,43452,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... mariés depuis cinq ans quand ils ont signé ces documents ensemble.'::text,'étaient'::text,'sont'::text,'ont été'::text,'Ils étaient mariés depuis cinq ans quand ils ont signé ces documents ensemble.'::text),
(391067,43452,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu belgeleri birlikte imzaladıklarında beş yıldır ...'::text,'evliydiler'::text,'evliler'::text,'evli oldular'::text,'Bu belgeleri birlikte imzaladıklarında beş yıldır evliydiler.'::text),
(391068,43452,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már öt éve ... házasok, amikor együtt aláírták ezeket a dokumentumokat.'::text,'voltak'::text,NULL::text,'voltak'::text,'Már öt éve voltak házasok, amikor együtt aláírták ezeket a dokumentumokat.'::text),
(338187,37577,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade das Haarspray, als der Umhang fast herunterrutschte. Katastrophe!'::text,'sprühte'::text,'sprühte'::text,'hat gesprüht'::text,'Sie sprühte gerade das Haarspray, als der Umhang fast herunterrutschte. Katastrophe!'::text),
(338191,37577,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... лак для волосся, коли накидка мало не зісковзнула. Катастрофа!'::text,'розпилювала'::text,'розпилила'::text,'розпилила'::text,'Вона розпилювала лак для волосся, коли накидка мало не зісковзнула. Катастрофа!'::text),
(338190,37577,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la laca cuando la capa casi se resbaló. ¡Desastre!'::text,'Estaba echando'::text,'Echó'::text,'Ha echado'::text,'Estaba echando la laca cuando la capa casi se resbaló. ¡Desastre!'::text),
(338189,37577,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la laque quand la cape a failli glisser. Catastrophe !'::text,'vaporisait'::text,'vaporisa'::text,'a vaporisé'::text,'Elle vaporisait la laque quand la cape a failli glisser. Catastrophe !'::text),
(338192,37577,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pelerin neredeyse kaydığında ... saç spreyini. Felaket!'::text,'sıkıyordu'::text,'sıktı'::text,'sıkmış'::text,'Pelerin neredeyse kaydığında sıkıyordu saç spreyini. Felaket!'::text),
(338193,37577,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a hajlakkot, amikor a pelerin majdnem lecsúszott. Katasztrófa!'::text,'fújta'::text,'kifújta'::text,'kifújta már'::text,'Épp fújta a hajlakkot, amikor a pelerin majdnem lecsúszott. Katasztrófa!'::text),
(338196,37578,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht nur ... den Rücken der Kundin, sondern er schützt auch ihre Kleidung.'::text,'bedeckt der Umhang'::text,'der Umhang bedeckt'::text,'bedeckt der Umhang'::text,'Nicht nur bedeckt der Umhang den Rücken der Kundin, sondern er schützt auch ihre Kleidung.'::text),
(338200,37578,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не лише ... спину клієнтки, а й захищає її одяг.'::text,'накидка закриває'::text,'накидка закриває'::text,'закриває накидка'::text,'Не лише накидка закриває спину клієнтки, а й захищає її одяг.'::text),
(338199,37578,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No solo ... la espalda de la clienta, sino que también protege su ropa.'::text,'cubre la capa'::text,'la capa cubre'::text,'cubre la capa'::text,'No solo cubre la capa la espalda de la clienta, sino que también protege su ropa.'::text),
(338198,37578,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non seulement ... le dos de la cliente, mais elle protège aussi ses vêtements.'::text,'la cape couvre'::text,'la cape couvre'::text,'couvre la cape'::text,'Non seulement la cape couvre le dos de la cliente, mais elle protège aussi ses vêtements.'::text),
(338201,37578,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pelerin sadece müşterinin sırtını ... kalmıyor, kıyafetlerini de koruyor.'::text,'örtmekle'::text,'örtmekle'::text,'örtmekle'::text,'Pelerin sadece müşterinin sırtını örtmekle kalmıyor, kıyafetlerini de koruyor.'::text),
(338202,37578,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nemcsak ... a vendég hátát, hanem a ruháját is védi.'::text,'takarja a pelerin'::text,'a pelerin takarja'::text,'takarja a pelerin'::text,'Nemcsak takarja a pelerin a vendég hátát, hanem a ruháját is védi.'::text),
(338214,37580,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat mir gesagt, sie wünschte, der Umhang ... weniger heiß.'::text,'wäre'::text,'ist'::text,'wird'::text,'Bestie, sie hat mir gesagt, sie wünschte, der Umhang wäre weniger heiß.'::text),
(338218,37580,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що хотіла б, щоб накидка ... менш гарячою.'::text,'була'::text,'є'::text,'буде'::text,'Подруго, вона сказала мені, що хотіла б, щоб накидка була менш гарячою.'::text),
(338217,37580,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ojalá la capa ... menos calurosa.'::text,'fuera'::text,'es'::text,'será'::text,'Amiga, me dijo que ojalá la capa fuera menos calurosa.'::text),
(338216,37580,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma bestie, elle m''a dit qu''elle aimerait que la cape ... moins chaude.'::text,'soit'::text,'est'::text,'sera'::text,'Ma bestie, elle m''a dit qu''elle aimerait que la cape soit moins chaude.'::text),
(338219,37580,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, keşke pelerin daha az sıcak ... dedi bana.'::text,'olsa'::text,NULL::text,'olacak'::text,'Kanka, keşke pelerin daha az sıcak olsa dedi bana.'::text),
(338220,37580,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, bárcsak a pelerin kevésbé ... meleg.'::text,'lenne'::text,NULL::text,'lesz'::text,'Csajszi, azt mondta, bárcsak a pelerin kevésbé lenne meleg.'::text),
(338223,37581,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast einen Salon gewählt, ... Stylisten nie den Umhang vergessen, und ehrlich, Respekt.'::text,'dessen'::text,'welchen'::text,'der'::text,'Du hast einen Salon gewählt, dessen Stylisten nie den Umhang vergessen, und ehrlich, Respekt.'::text),
(338227,37581,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти обрала салон, ... стилісти ніколи не забувають про накидку, і чесно, респект.'::text,'чиї'::text,'який'::text,'хто'::text,'Ти обрала салон, чиї стилісти ніколи не забувають про накидку, і чесно, респект.'::text),
(338226,37581,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elegiste un salón ... estilistas nunca se olvidan de la capa, y sinceramente, respeto.'::text,'cuyos'::text,'que'::text,'quien'::text,'Elegiste un salón cuyos estilistas nunca se olvidan de la capa, y sinceramente, respeto.'::text),
(338225,37581,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as choisi un salon ... les coiffeurs n''oublient jamais la cape, et franchement, respect.'::text,'dont'::text,'que'::text,'qui'::text,'Tu as choisi un salon dont les coiffeurs n''oublient jamais la cape, et franchement, respect.'::text),
(338228,37581,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuaförleri pelerini asla unutmayan bir salon ... seçtin ve açıkçası, saygı.'::text,''::text,NULL::text,NULL::text,'Kuaförleri pelerini asla unutmayan bir salon seçtin ve açıkçası, saygı.'::text),
(338229,37581,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan szalont választottál, ... fodrászai sosem felejtik el a pelerint, és őszintén, respekt.'::text,'amelynek a'::text,'amelyet'::text,'aki'::text,'Olyan szalont választottál, amelynek a fodrászai sosem felejtik el a pelerint, és őszintén, respekt.'::text),
(338232,37582,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist selten, und ehrlich, du saßt unter dem Umhang still wie eine Legende.'::text,'Geduld'::text,'Die Geduld'::text,'Eine Geduld'::text,'Geduld ist selten, und ehrlich, du saßt unter dem Umhang still wie eine Legende.'::text),
(338236,37582,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... — рідкість, і чесно, ти сиділа під тією накидкою нерухомо, як легенда.'::text,'Терпіння'::text,'Терпіння'::text,'Терпіння'::text,'Терпіння — рідкість, і чесно, ти сиділа під тією накидкою нерухомо, як легенда.'::text),
(338235,37582,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... es algo raro, y sinceramente, te quedaste quieta bajo esa capa como una leyenda.'::text,'La paciencia'::text,'La paciencia'::text,'Una paciencia'::text,'La paciencia es algo raro, y sinceramente, te quedaste quieta bajo esa capa como una leyenda.'::text),
(338234,37582,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est rare, et franchement, tu es restée immobile sous cette cape comme une légende.'::text,'La patience'::text,'La patience'::text,'Une patience'::text,'La patience est rare, et franchement, tu es restée immobile sous cette cape comme une légende.'::text),
(338237,37582,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... nadir bulunur ve açıkçası o pelerinin altında efsane gibi kıpırdamadan oturdun.'::text,'Sabır'::text,'Sabır'::text,'Bir sabır'::text,'Sabır nadir bulunur ve açıkçası o pelerinin altında efsane gibi kıpırdamadan oturdun.'::text),
(338238,37582,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ritka, és őszintén, úgy ültél mozdulatlanul abban a pelerinben, mint egy legenda.'::text,'A türelem'::text,'A türelem'::text,'Egy türelem'::text,'A türelem ritka, és őszintén, úgy ültél mozdulatlanul abban a pelerinben, mint egy legenda.'::text),
(338241,37583,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dem Umhang landete das Haarspray natürlich nirgendwo anders. Makellos.'::text,'Dank'::text,'Trotz'::text,'Statt'::text,'Dank dem Umhang landete das Haarspray natürlich nirgendwo anders. Makellos.'::text),
(338245,37583,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... накидці лак, звісно ж, більше ніде не опинився. Бездоганно.'::text,'Завдяки'::text,'Попри'::text,'Замість'::text,'Завдяки накидці лак, звісно ж, більше ніде не опинився. Бездоганно.'::text),
(338244,37583,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la capa, la laca obviamente no cayó en ningún otro sitio. Impecable.'::text,'Gracias a'::text,'A pesar de'::text,'En lugar de'::text,'Gracias a la capa, la laca obviamente no cayó en ningún otro sitio. Impecable.'::text),
(338243,37583,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la cape, la laque n''a évidemment atterri nulle part ailleurs. Parfait.'::text,'Grâce à'::text,'Malgré'::text,'Au lieu de'::text,'Grâce à la cape, la laque n''a évidemment atterri nulle part ailleurs. Parfait.'::text),
(338246,37583,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pelerin ..., saç spreyi tabii ki başka hiçbir yere gitmedi. Kusursuz.'::text,'sayesinde'::text,'rağmen'::text,'yerine'::text,'Pelerin sayesinde, saç spreyi tabii ki başka hiçbir yere gitmedi. Kusursuz.'::text),
(338247,37583,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pelerinnek ... a hajlakk nyilván sehova máshova nem került. Hibátlan.'::text,'köszönhetően'::text,'ellenére'::text,'helyett'::text,'A pelerinnek köszönhetően a hajlakk nyilván sehova máshova nem került. Hibátlan.'::text),
(338250,37584,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wusste, der Umhang ... ihre Kleidung vor dem Spray schützen. Ganz klar ein makelloser Plan.'::text,'würde'::text,'wird'::text,'wird'::text,'Sie wusste, der Umhang würde ihre Kleidung vor dem Spray schützen. Ganz klar ein makelloser Plan.'::text),
(338254,37584,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона знала, що накидка ... її одяг від лаку. Явно бездоганний план.'::text,'захистить'::text,'захистить'::text,'захищає'::text,'Вона знала, що накидка захистить її одяг від лаку. Явно бездоганний план.'::text),
(338253,37584,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabía que la capa ... su ropa del espray. Claramente un plan impecable.'::text,'protegería'::text,'protegerá'::text,'protege'::text,'Sabía que la capa protegería su ropa del espray. Claramente un plan impecable.'::text),
(338252,37584,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle savait que la cape ... ses vêtements de la laque. Clairement un plan parfait.'::text,'protégerait'::text,'protégera'::text,'protège'::text,'Elle savait que la cape protégerait ses vêtements de la laque. Clairement un plan parfait.'::text),
(338255,37584,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pelerinin kıyafetlerini spreyden ... biliyordu. Belli ki kusursuz bir plan.'::text,'koruyacağını'::text,'koruyacağını'::text,'koruduğunu'::text,'Pelerinin kıyafetlerini spreyden koruyacağını biliyordu. Belli ki kusursuz bir plan.'::text),
(338256,37584,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudta, hogy a pelerin ... a ruháját a laktól. Nyilván hibátlan terv.'::text,'megvédi majd'::text,'meg fogja védeni'::text,'megvédi'::text,'Tudta, hogy a pelerin megvédi majd a ruháját a laktól. Nyilván hibátlan terv.'::text),
(338259,37585,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... die Kundin mit einem schwarzen Umhang im Stuhl.'::text,'sitzt'::text,'sitzt'::text,'hat gesessen'::text,'Gerade sitzt die Kundin mit einem schwarzen Umhang im Stuhl.'::text),
(338263,37585,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз клієнтка ... у кріслі в чорній накидці.'::text,'сидить'::text,'сидить'::text,'сиділа'::text,'Зараз клієнтка сидить у кріслі в чорній накидці.'::text),
(338262,37585,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, la clienta ... en la silla con una capa negra.'::text,'está sentada'::text,'se sienta'::text,'se ha sentado'::text,'Ahora mismo, la clienta está sentada en la silla con una capa negra.'::text),
(338261,37585,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la cliente ... dans le fauteuil avec une cape noire.'::text,'est assise'::text,'s''assoit'::text,'s''est assise'::text,'En ce moment, la cliente est assise dans le fauteuil avec une cape noire.'::text),
(338264,37585,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda müşteri siyah bir pelerinle koltukta ...'::text,'oturuyor'::text,'oturur'::text,'oturdu'::text,'Şu anda müşteri siyah bir pelerinle koltukta oturuyor.'::text),
(338265,37585,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendég épp most ... a székben egy fekete pelerinben.'::text,'ül'::text,'ül'::text,'ült'::text,'A vendég épp most ül a székben egy fekete pelerinben.'::text),
(338268,37586,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kundin ... den Umhang schon eine Stunde getragen, als die Friseurin ihr endlich die Haare einsprühte.'::text,'hatte'::text,'hat'::text,'trug'::text,'Die Kundin hatte den Umhang schon eine Stunde getragen, als die Friseurin ihr endlich die Haare einsprühte.'::text),
(338272,37586,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клієнтка ... накидку вже годину, коли стилістка нарешті збризнула їй волосся лаком.'::text,'носила'::text,'носить'::text,'носила'::text,'Клієнтка носила накидку вже годину, коли стилістка нарешті збризнула їй волосся лаком.'::text),
(338271,37586,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La clienta ... la capa desde hacía una hora cuando la estilista por fin le echó laca.'::text,'llevaba puesta'::text,'lleva puesta'::text,'llevaba puesta'::text,'La clienta llevaba puesta la capa desde hacía una hora cuando la estilista por fin le echó laca.'::text),
(338270,37586,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cliente ... la cape depuis une heure quand la coiffeuse lui a enfin vaporisé les cheveux.'::text,'portait'::text,'porte'::text,'portait'::text,'La cliente portait la cape depuis une heure quand la coiffeuse lui a enfin vaporisé les cheveux.'::text),
(338273,37586,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuaför sonunda saçına sprey sıktığında müşteri bir saattir pelerin ...'::text,'takıyordu'::text,'takıyor'::text,'takıyordu'::text,'Kuaför sonunda saçına sprey sıktığında müşteri bir saattir pelerin takıyordu.'::text),
(338274,37586,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendég már egy órája ... a pelerint, amikor a fodrász végre befújta a haját.'::text,'viselte'::text,'viseli'::text,'viselte'::text,'A vendég már egy órája viselte a pelerint, amikor a fodrász végre befújta a haját.'::text),
(338277,37587,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis das Spray trocken ist, wird die Friseurin den Umhang ...'::text,'abgenommen haben'::text,'abnehmen'::text,'abnehmen'::text,'Bis das Spray trocken ist, wird die Friseurin den Umhang abgenommen haben.'::text),
(338281,37587,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки лак висохне, стилістка ... накидку.'::text,'зніме'::text,'зніме'::text,'знімає'::text,'Поки лак висохне, стилістка зніме накидку.'::text),
(338280,37587,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se seque la laca, la estilista ... la capa.'::text,'habrá quitado'::text,'quitará'::text,'quita'::text,'Para cuando se seque la laca, la estilista habrá quitado la capa.'::text),
(338279,37587,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce que la laque sèche, la coiffeuse ... la cape.'::text,'aura retiré'::text,'retirera'::text,'retire'::text,'D''ici à ce que la laque sèche, la coiffeuse aura retiré la cape.'::text),
(338282,37587,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sprey kuruyana kadar kuaför pelerini ...'::text,'çıkarmış olacak'::text,'çıkaracak'::text,'çıkarıyor'::text,'Sprey kuruyana kadar kuaför pelerini çıkarmış olacak.'::text),
(338283,37587,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a lakk megszárad, a fodrász ... a pelerint.'::text,'leveszi'::text,'le fogja venni'::text,'leveszi'::text,'Mire a lakk megszárad, a fodrász leveszi a pelerint.'::text),
(353631,39293,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... seit Jahren an ihrer Fitness, ohne Witz.'::text,'arbeitet'::text,'arbeitet gerade'::text,'arbeitet'::text,'Bro, sie arbeitet seit Jahren an ihrer Fitness, ohne Witz.'::text),
(353635,39293,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... над своєю формою вже роками, без брехні.'::text,'працює'::text,'працює'::text,'працює'::text,'Бро, вона працює над своєю формою вже роками, без брехні.'::text),
(353634,39293,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... en su forma física desde hace años, en serio.'::text,'ha estado trabajando'::text,'está trabajando'::text,'trabaja'::text,'Bro, ha estado trabajando en su forma física desde hace años, en serio.'::text),
(353633,39293,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... sa forme physique depuis des années, sans mentir.'::text,'travaille'::text,'est en train de travailler'::text,'travaille'::text,'Frérot, elle travaille sa forme physique depuis des années, sans mentir.'::text),
(353636,39293,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yıllardır kondisyonu için ..., yemin ederim.'::text,'çalışıyor'::text,'çalışıyor'::text,'çalışır'::text,'Kanka, yıllardır kondisyonu için çalışıyor, yemin ederim.'::text),
(353637,39293,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, évek óta ... az erőnlétén, komolyan.'::text,'dolgozik'::text,'dolgozik'::text,'dolgozik'::text,'Tesó, évek óta dolgozik az erőnlétén, komolyan.'::text),
(353640,39294,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie ... gerade eine Orange aus, als die ganze Bar wegen ihrer Fitness zu jubeln anfing.'::text,'presste'::text,'presste'::text,'hat'::text,'Yo, sie presste gerade eine Orange aus, als die ganze Bar wegen ihrer Fitness zu jubeln anfing.'::text),
(353644,39294,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вона ... апельсин, коли весь бар почав радіти її формі.'::text,'вичавлювала'::text,'вичавила'::text,'вичавила'::text,'Йо, вона вичавлювала апельсин, коли весь бар почав радіти її формі.'::text),
(353643,39294,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ... una naranja cuando todo el bar empezó a aplaudir su forma física.'::text,'estaba exprimiendo'::text,'exprimió'::text,'ha exprimido'::text,'Oye, estaba exprimiendo una naranja cuando todo el bar empezó a aplaudir su forma física.'::text),
(353642,39294,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, elle ... une orange quand tout le bar s''est mis à applaudir sa forme physique.'::text,'pressait'::text,'a pressé'::text,'a pressé'::text,'Wesh, elle pressait une orange quand tout le bar s''est mis à applaudir sa forme physique.'::text),
(353645,39294,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bütün bar kondisyonu için tezahürat yapmaya başladığında bir portakal ...'::text,'sıkıyordu'::text,'sıktı'::text,'sıkmış'::text,'Kanka, bütün bar kondisyonu için tezahürat yapmaya başladığında bir portakal sıkıyordu.'::text),
(353646,39294,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, épp ... egy narancsot, amikor az egész bár ujjongani kezdett az erőnléte miatt.'::text,'facsart'::text,'kifacsart'::text,'kifacsart már'::text,'Tesó, épp facsart egy narancsot, amikor az egész bár ujjongani kezdett az erőnléte miatt.'::text),
(353649,39295,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Fitnessroutine ... bisher 40 Wassermelonen zu Saft verarbeitet, über dem Ziel.'::text,'hat'::text,'hat'::text,'verarbeitet'::text,'Ihre Fitnessroutine hat bisher 40 Wassermelonen zu Saft verarbeitet, über dem Ziel.'::text),
(353653,39295,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її фітнес-режим уже ... 40 кавунів на сік, понад план.'::text,'перетворив'::text,'перетворював'::text,'перетворює'::text,'Її фітнес-режим уже перетворив 40 кавунів на сік, понад план.'::text),
(353652,39295,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su rutina de fitness ... 40 sandías en zumo hasta ahora, por encima del objetivo.'::text,'ha convertido'::text,'ha estado convirtiendo'::text,'está convirtiendo'::text,'Su rutina de fitness ha convertido 40 sandías en zumo hasta ahora, por encima del objetivo.'::text),
(353651,39295,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa routine fitness ... 40 pastèques en jus jusqu''ici, au-dessus de l''objectif.'::text,'a transformé'::text,'transforme depuis un moment'::text,'est en train de transformer'::text,'Sa routine fitness a transformé 40 pastèques en jus jusqu''ici, au-dessus de l''objectif.'::text),
(353654,39295,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fitness rutini şimdiye kadar 40 karpuzu meyve suyuna ..., hedefin üzerinde.'::text,'dönüştürdü'::text,'dönüştürüp duruyor'::text,'dönüştürüyor'::text,'Fitness rutini şimdiye kadar 40 karpuzu meyve suyuna dönüştürdü, hedefin üzerinde.'::text),
(353655,39295,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edzésrutinja eddig 40 görögdinnyét ... lévé, a cél felett.'::text,'változtatott'::text,'változtat'::text,'éppen változtat'::text,'Az edzésrutinja eddig 40 görögdinnyét változtatott lévé, a cél felett.'::text),
(353658,39296,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor der Party ... sie viel Fitnesstraining gemacht, weil man so fit wird.'::text,'hatte'::text,'hat'::text,'macht'::text,'Vor der Party hatte sie viel Fitnesstraining gemacht, weil man so fit wird.'::text),
(353662,39296,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перед вечіркою вона ... багато фітнес-тренувань, бо саме так приходять у форму.'::text,'провела'::text,'провела'::text,'проводить'::text,'Перед вечіркою вона провела багато фітнес-тренувань, бо саме так приходять у форму.'::text),
(353661,39296,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de la fiesta, ... mucho entrenamiento físico, porque así es como te pones en forma.'::text,'había hecho'::text,'ha hecho'::text,'hace'::text,'Antes de la fiesta, había hecho mucho entrenamiento físico, porque así es como te pones en forma.'::text),
(353660,39296,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant la fête, elle ... beaucoup d''entraînement, parce que c''est comme ça qu''on se met en forme.'::text,'avait fait'::text,'a fait'::text,'fait'::text,'Avant la fête, elle avait fait beaucoup d''entraînement, parce que c''est comme ça qu''on se met en forme.'::text),
(353663,39296,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Partiden önce çok fazla fitness antrenmanı ..., çünkü forma böyle girilir.'::text,'yapmıştı'::text,'yaptı'::text,'yapıyor'::text,'Partiden önce çok fazla fitness antrenmanı yapmıştı, çünkü forma böyle girilir.'::text),
(353664,39296,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A buli előtt ... sok erőnléti edzést, mert így lesz fitt az ember.'::text,'csinált végig'::text,'csinált'::text,'csinál'::text,'A buli előtt csinált végig sok erőnléti edzést, mert így lesz fitt az ember.'::text),
(353667,39297,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie ihre Fitness hält, ... sie nächstes Mal eine ganze Ananas.'::text,'zerquetscht'::text,'zerquetschte'::text,'zerquetschte'::text,'Wenn sie ihre Fitness hält, zerquetscht sie nächstes Mal eine ganze Ananas.'::text),
(353671,39297,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона збереже форму, наступного разу ... цілий ананас.'::text,'розчавить'::text,'розчавила б'::text,'розчавила'::text,'Якщо вона збереже форму, наступного разу розчавить цілий ананас.'::text),
(353670,39297,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si mantiene su forma física, la próxima vez ... una piña entera.'::text,'aplastará'::text,'aplastaría'::text,'aplastó'::text,'Si mantiene su forma física, la próxima vez aplastará una piña entera.'::text),
(353669,39297,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle garde sa forme, la prochaine fois elle ... un ananas entier.'::text,'écrasera'::text,'écraserait'::text,'a écrasé'::text,'Si elle garde sa forme, la prochaine fois elle écrasera un ananas entier.'::text),
(353672,39297,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kondisyonunu korursa bir dahaki sefere koca bir ananası ...'::text,'ezecek'::text,'ezerdi'::text,'ezdi'::text,'Kondisyonunu korursa bir dahaki sefere koca bir ananası ezecek.'::text),
(353673,39297,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha megtartja az erőnlétét, legközelebb ... egy egész ananászt.'::text,'szétroppant'::text,'szétroppantana'::text,'szétroppantott'::text,'Ha megtartja az erőnlétét, legközelebb szétroppant egy egész ananászt.'::text),
(353676,39298,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich ihre Fitness hätte, ... ich auch eine Wassermelone mit bloßen Händen.'::text,'zerquetschte'::text,'zerquetsche'::text,'zerquetsche'::text,'Wenn ich ihre Fitness hätte, zerquetschte ich auch eine Wassermelone mit bloßen Händen.'::text),
(353680,39298,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби я мав таку форму, як вона, я теж ... кавун руками.'::text,'розчавив би'::text,'розчавлю'::text,'чавлю'::text,'Якби я мав таку форму, як вона, я теж розчавив би кавун руками.'::text),
(353679,39298,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tuviera su forma física, yo también ... una sandía con las manos.'::text,'aplastaría'::text,'aplastaré'::text,'aplasto'::text,'Si tuviera su forma física, yo también aplastaría una sandía con las manos.'::text),
(353678,39298,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si j''avais sa forme physique, je ... aussi une pastèque à mains nues.'::text,'écraserais'::text,'écraserai'::text,'écrase'::text,'Si j''avais sa forme physique, je écraserais aussi une pastèque à mains nues.'::text),
(353681,39298,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun kondisyonu bende olsaydı, ben de elimle bir karpuzu ...'::text,'ezerdim'::text,'ezeceğim'::text,'ezerim'::text,'Onun kondisyonu bende olsaydı, ben de elimle bir karpuzu ezerdim.'::text),
(353682,39298,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nekem lenne ilyen erőnlétem, én is ... egy görögdinnyét a kezemmel.'::text,'szétroppantanék'::text,'szétroppantok majd'::text,'szétroppantok'::text,'Ha nekem lenne ilyen erőnlétem, én is szétroppantanék egy görögdinnyét a kezemmel.'::text),
(353685,39299,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Saft ... heute Nachmittag von einer Fitnesstrainerin von Hand gemacht.'::text,'wurde'::text,'wird'::text,'hat'::text,'Der Saft wurde heute Nachmittag von einer Fitnesstrainerin von Hand gemacht.'::text),
(353689,39299,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сік ... сьогодні вдень вручну фітнес-тренеркою.'::text,'був приготовлений'::text,'готується'::text,'приготувала'::text,'Сік був приготовлений сьогодні вдень вручну фітнес-тренеркою.'::text),
(353688,39299,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El zumo ... a mano por una entrenadora de fitness esta tarde.'::text,'fue hecho'::text,'es hecho'::text,'hizo'::text,'El zumo fue hecho a mano por una entrenadora de fitness esta tarde.'::text),
(353687,39299,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jus ... à la main par une coach sportive cet après-midi.'::text,'a été fait'::text,'est fait'::text,'a fait'::text,'Le jus a été fait à la main par une coach sportive cet après-midi.'::text),
(353690,39299,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meyve suyu bu öğleden sonra bir fitness koçu tarafından elle ...'::text,'yapıldı'::text,'yapılır'::text,'yaptı'::text,'Meyve suyu bu öğleden sonra bir fitness koçu tarafından elle yapıldı.'::text),
(353691,39299,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lé ma délután ... kézzel, egy fitneszedző által.'::text,'készült'::text,'készül'::text,'készített'::text,'A lé ma délután készült kézzel, egy fitneszedző által.'::text),
(353694,39300,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Fitness ... die Wassermelone komplett!'::text,'zerstörte'::text,'wurde zerstört'::text,'zerstörend'::text,'Ihre Fitness zerstörte die Wassermelone komplett!'::text),
(353698,39300,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її форма ... той кавун повністю!'::text,'знищила'::text,'була знищена'::text,'знищуючи'::text,'Її форма знищила той кавун повністю!'::text),
(353697,39300,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su forma física ... esa sandía por completo!'::text,'destrozó'::text,'fue destrozada'::text,'destrozando'::text,'¡Su forma física destrozó esa sandía por completo!'::text),
(353696,39300,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa forme physique ... cette pastèque complètement !'::text,'a détruit'::text,'a été détruite'::text,'détruisant'::text,'Sa forme physique a détruit cette pastèque complètement !'::text),
(353699,39300,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kondisyonu o karpuzu tamamen ...!'::text,'yok etti'::text,'yok edildi'::text,'yok eden'::text,'Kondisyonu o karpuzu tamamen yok etti!'::text),
(353700,39300,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az erőnléte teljesen ... azt a görögdinnyét!'::text,'szétzúzta'::text,'szét lett zúzva'::text,'szétzúzva'::text,'Az erőnléte teljesen szétzúzta azt a görögdinnyét!'::text),
(353703,39301,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine ganze Wassermelone zerquetscht! Ihre Fitness ... absolut unfassbar sein!'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Eine ganze Wassermelone zerquetscht! Ihre Fitness muss absolut unfassbar sein!'::text),
(353707,39301,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цілий кавун розчавлений! Її форма ... бути просто нереальною!'::text,'мусить'::text,'не може'::text,'не повинна'::text,'Цілий кавун розчавлений! Її форма мусить бути просто нереальною!'::text),
(353706,39301,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Una sandía entera aplastada! ¡Su forma física ... ser totalmente irreal!'::text,'debe de'::text,'no puede'::text,'no debería'::text,'¡Una sandía entera aplastada! ¡Su forma física debe de ser totalmente irreal!'::text),
(353705,39301,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une pastèque entière écrasée ! Sa forme physique ... être complètement dingue !'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Une pastèque entière écrasée ! Sa forme physique doit être complètement dingue !'::text),
(353708,39301,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koca bir karpuz ezildi! Kondisyonu kesinlikle inanılmaz ...!'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Koca bir karpuz ezildi! Kondisyonu kesinlikle inanılmaz olmalı!'::text),
(353709,39301,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy egész görögdinnye szétroppantva! Az erőnlétének ... elképesztőnek lennie!'::text,'kell'::text,'nem lehet'::text,'nem kellene'::text,'Egy egész görögdinnye szétroppantva! Az erőnlétének kell elképesztőnek lennie!'::text),
(353712,39302,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, die Frau, ... Fitness die Wassermelone zerquetscht hat, hat mir gesagt, es war leicht.'::text,'deren'::text,'die'::text,'was'::text,'Süße, die Frau, deren Fitness die Wassermelone zerquetscht hat, hat mir gesagt, es war leicht.'::text),
(353716,39302,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, жінка, ... форма розчавила той кавун, сказала мені, що це було легко.'::text,'чия'::text,'яка'::text,'що'::text,'Подруго, жінка, чия форма розчавила той кавун, сказала мені, що це було легко.'::text),
(353715,39302,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, la mujer ... forma física aplastó esa sandía me dijo que fue fácil.'::text,'cuya'::text,'que'::text,'la cual'::text,'Tía, la mujer cuya forma física aplastó esa sandía me dijo que fue fácil.'::text),
(353714,39302,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, la femme ... la forme physique a écrasé cette pastèque m''a dit que c''était facile.'::text,'dont'::text,'qui'::text,'que'::text,'Meuf, la femme dont la forme physique a écrasé cette pastèque m''a dit que c''était facile.'::text),
(353717,39302,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, kondisyonu o karpuzu ezen kadın ... bana kolay olduğunu söyledi.'::text,''::text,NULL::text,NULL::text,'Kızım, kondisyonu o karpuzu ezen kadın bana kolay olduğunu söyledi.'::text),
(353718,39302,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a nő, ... erőnléte szétroppantotta azt a görögdinnyét, azt mondta, hogy könnyű volt.'::text,'akinek az'::text,'aki'::text,'ami'::text,'Csajszi, a nő, akinek az erőnléte szétroppantotta azt a görögdinnyét, azt mondta, hogy könnyű volt.'::text),
(399612,44402,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Team Einheit ..., steigt die Produktivität um 20 Prozent.'::text,'hat'::text,'hatte'::text,'haben wird'::text,'Wenn ein Team Einheit hat, steigt die Produktivität um 20 Prozent.'::text),
(399616,44402,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо в команди ... єдність, продуктивність зростає на 20 відсотків.'::text,'є'::text,'була'::text,'буде'::text,'Якщо в команди є єдність, продуктивність зростає на 20 відсотків.'::text),
(399615,44402,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un equipo ... unidad, la productividad sube un 20 por ciento.'::text,'tiene'::text,'tenía'::text,'tendrá'::text,'Si un equipo tiene unidad, la productividad sube un 20 por ciento.'::text),
(399614,44402,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une équipe ... de l''unité, la productivité augmente de 20 pour cent.'::text,'a'::text,'avait'::text,'aura'::text,'Si une équipe a de l''unité, la productivité augmente de 20 pour cent.'::text),
(399617,44402,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir ekipte birlik ..., verimlilik yüzde 20 artar.'::text,'varsa'::text,'vardıysa'::text,'olacaksa'::text,'Bir ekipte birlik varsa, verimlilik yüzde 20 artar.'::text),
(399618,44402,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy csapatban ... egység, a termelékenység 20 százalékkal nő.'::text,'van'::text,'volt'::text,'lesz'::text,'Ha egy csapatban van egység, a termelékenység 20 százalékkal nő.'::text),
(399621,44403,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sich alle zusammen umarmen, ... es Einheit, weil sie zusammen sind.'::text,'gibt'::text,'gäbe'::text,'gab'::text,'Wenn sich alle zusammen umarmen, gibt es Einheit, weil sie zusammen sind.'::text),
(399625,44403,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вони всі разом обіймуться, ... єдність, бо вони разом.'::text,'буде'::text,'була б'::text,'була'::text,'Якщо вони всі разом обіймуться, буде єдність, бо вони разом.'::text),
(399624,44403,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si todos se abrazan juntos, ... unidad, porque están juntos.'::text,'habrá'::text,'habría'::text,'hubo'::text,'Si todos se abrazan juntos, habrá unidad, porque están juntos.'::text),
(399623,44403,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils se font tous un câlin ensemble, il y ... de l''unité, parce qu''ils sont ensemble.'::text,'aura'::text,'aurait'::text,'a eu'::text,'S''ils se font tous un câlin ensemble, il y aura de l''unité, parce qu''ils sont ensemble.'::text),
(399626,44403,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hepsi birlikte sarılırsa birlik ..., çünkü birlikteler.'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Hepsi birlikte sarılırsa birlik olacak, çünkü birlikteler.'::text),
(399627,44403,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha mindannyian együtt ölelkeznek, ... egység, mert együtt vannak.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha mindannyian együtt ölelkeznek, lesz egység, mert együtt vannak.'::text),
(399630,44404,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Personal keine Einheit ..., würde sich der Service typischerweise erheblich verlangsamen.'::text,'hätte'::text,'hat'::text,'haben würde'::text,'Wenn das Personal keine Einheit hätte, würde sich der Service typischerweise erheblich verlangsamen.'::text),
(399634,44404,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби персонал ... єдності, обслуговування, як правило, суттєво сповільнилося б.'::text,'не мав'::text,'не має'::text,'не мав би'::text,'Якби персонал не мав єдності, обслуговування, як правило, суттєво сповільнилося б.'::text),
(399633,44404,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el personal no ... unidad, el servicio normalmente se ralentizaría bastante.'::text,'tuviera'::text,'tiene'::text,'tendría'::text,'Si el personal no tuviera unidad, el servicio normalmente se ralentizaría bastante.'::text),
(399632,44404,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le personnel ne ... aucune unité, le service ralentirait généralement beaucoup.'::text,'possédait'::text,'possède'::text,'posséderait'::text,'Si le personnel ne possédait aucune unité, le service ralentirait généralement beaucoup.'::text),
(399635,44404,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personelde hiç birlik ..., servis genellikle ciddi şekilde yavaşlardı.'::text,'olmasaydı'::text,'yok'::text,'olmazdı'::text,'Personelde hiç birlik olmasaydı, servis genellikle ciddi şekilde yavaşlardı.'::text),
(399636,44404,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a személyzetben nem ... egység, a kiszolgálás jellemzően jelentősen lelassulna.'::text,'lenne'::text,'van'::text,'lenne'::text,'Ha a személyzetben nem lenne egység, a kiszolgálás jellemzően jelentősen lelassulna.'::text),
(399639,44405,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Einheit ... am Ende der Schicht durch eine große Gruppenumarmung gezeigt.'::text,'wurde'::text,'zeigte'::text,'zeigt'::text,'Ihre Einheit wurde am Ende der Schicht durch eine große Gruppenumarmung gezeigt.'::text),
(399643,44405,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їхню єдність ... наприкінці зміни одними великими груповими обіймами.'::text,'показали'::text,'показала'::text,'показує'::text,'Їхню єдність показали наприкінці зміни одними великими груповими обіймами.'::text),
(399642,44405,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su unidad ... al final del turno con un gran abrazo de grupo.'::text,'fue mostrada'::text,'mostró'::text,'está mostrando'::text,'Su unidad fue mostrada al final del turno con un gran abrazo de grupo.'::text),
(399641,44405,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leur unité ... à la fin du service par un grand câlin collectif.'::text,'a été montrée'::text,'a montré'::text,'est en train de montrer'::text,'Leur unité a été montrée à la fin du service par un grand câlin collectif.'::text),
(399644,44405,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birlikleri vardiyanın sonunda büyük bir grup sarılmasıyla ...'::text,'gösterildi'::text,'gösterdi'::text,'gösteriyor'::text,'Birlikleri vardiyanın sonunda büyük bir grup sarılmasıyla gösterildi.'::text),
(399645,44405,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egységük a műszak végén ... egy nagy csoportos öleléssel.'::text,'meg lett mutatva'::text,'megmutatta'::text,'éppen mutatja'::text,'Az egységük a műszak végén meg lett mutatva egy nagy csoportos öleléssel.'::text),
(399648,44406,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein lauter Ruf „Service!“ ... die Einheit des ganzen Teams.'::text,'zeigte'::text,'wurde gezeigt'::text,'zeigend'::text,'Ein lauter Ruf „Service!“ Zeigte die Einheit des ganzen Teams.'::text),
(399652,44406,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один гучний вигук «Сервіс!» ... єдність усієї команди.'::text,'показав'::text,'був показаний'::text,'показуючи'::text,'Один гучний вигук «Сервіс!» Показав єдність усієї команди.'::text),
(399651,44406,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un solo grito de «¡Servicio!» ... la unidad de todo el equipo.'::text,'mostró'::text,'fue mostrado'::text,'mostrando'::text,'Un solo grito de «¡Servicio!» Mostró la unidad de todo el equipo.'::text),
(399650,44406,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un seul grand cri de « Service ! » ... l''unité de toute l''équipe.'::text,'a montré'::text,'a été montré'::text,'montrant'::text,'Un seul grand cri de « Service ! » a montré l''unité de toute l''équipe.'::text),
(399653,44406,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir yüksek sesli “Servis!” bağırışı tüm ekibin birliğini ...'::text,'gösterdi'::text,'gösterildi'::text,'gösteren'::text,'Tek bir yüksek sesli “Servis!” bağırışı tüm ekibin birliğini gösterdi.'::text),
(399654,44406,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyetlen hangos „Szerviz!” kiáltás ... az egész csapat egységét.'::text,'megmutatta'::text,'meg lett mutatva'::text,'megmutatva'::text,'Egyetlen hangos „Szerviz!” kiáltás megmutatta az egész csapat egységét.'::text),
(399666,44408,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, die Einheit, ... dein Team zeigt, ist ikonisch.'::text,'die'::text,'wer'::text,'deren'::text,'Ehrlich, die Einheit, die dein Team zeigt, ist ikonisch.'::text),
(399670,44408,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, єдність, ... показує твоя команда, — культова.'::text,'яку'::text,'хто'::text,'чия'::text,'Чесно, єдність, яку показує твоя команда, — культова.'::text),
(399669,44408,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, la unidad ... muestra tu equipo es icónica.'::text,'que'::text,'quien'::text,'cuya'::text,'Sinceramente, la unidad que muestra tu equipo es icónica.'::text),
(399668,44408,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, l''unité ... ton équipe montre est iconique.'::text,'que'::text,'qui'::text,'dont'::text,'Franchement, l''unité que ton équipe montre est iconique.'::text),
(399671,44408,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası ekibinin gösterdiği birlik ... efsane.'::text,''::text,NULL::text,NULL::text,'Açıkçası ekibinin gösterdiği birlik efsane.'::text),
(399672,44408,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, az az egység, ... a csapatod mutat, ikonikus.'::text,'amit'::text,'aki'::text,'akinek a'::text,'Őszintén, az az egység, amit a csapatod mutat, ikonikus.'::text),
(399675,44409,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Für niemanden eine Überraschung: Der Chefkoch sagte, das Team ... den ganzen Abend Einheit gezeigt.'::text,'habe'::text,'hat'::text,'zeigt'::text,'Für niemanden eine Überraschung: Der Chefkoch sagte, das Team habe den ganzen Abend Einheit gezeigt.'::text),
(399679,44409,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, ніхто не здивований: шеф-кухар сказав, що команда весь вечір ... єдність.'::text,'показувала'::text,'показала'::text,'показує'::text,'Звісно, ніхто не здивований: шеф-кухар сказав, що команда весь вечір показувала єдність.'::text),
(399678,44409,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente una sorpresa para nadie: el chef dijo que el equipo ... unidad toda la noche.'::text,'había mostrado'::text,'ha mostrado'::text,'muestra'::text,'Claramente una sorpresa para nadie: el chef dijo que el equipo había mostrado unidad toda la noche.'::text),
(399677,44409,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, surprise pour personne : le chef a dit que l''équipe ... de l''unité toute la soirée.'::text,'avait montré'::text,'a montré'::text,'montre'::text,'Évidemment, surprise pour personne : le chef a dit que l''équipe avait montré de l''unité toute la soirée.'::text),
(399680,44409,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki kimse için sürpriz değil: şef, ekibin bütün akşam birlik ... söyledi.'::text,'göstermiş olduğunu'::text,'gösterdiğini'::text,'gösterdiğini'::text,'Belli ki kimse için sürpriz değil: şef, ekibin bütün akşam birlik göstermiş olduğunu söyledi.'::text),
(399681,44409,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván senkit sem lepett meg: a séf azt mondta, hogy a csapat egész este ... egységet.'::text,'mutatott'::text,'mutatott'::text,'mutat'::text,'Nyilván senkit sem lepett meg: a séf azt mondta, hogy a csapat egész este mutatott egységet.'::text),
(399684,44410,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Natürlich ... dieses Team null Einheit in der Küche.'::text,'hatte früher'::text,'hatte'::text,'war es gewohnt zu haben'::text,'Natürlich hatte früher dieses Team null Einheit in der Küche.'::text),
(399688,44410,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, у цієї команди ... нульова єдність на кухні.'::text,'раніше була'::text,'бувала'::text,'звикла бути'::text,'Звісно, у цієї команди раніше була нульова єдність на кухні.'::text),
(399687,44410,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, este equipo ... cero unidad en la cocina.'::text,'solía tener'::text,'tenía'::text,'estaba acostumbrado a tener'::text,'Obviamente, este equipo solía tener cero unidad en la cocina.'::text),
(399686,44410,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, cette équipe ... zéro unité en cuisine.'::text,'avait avant'::text,'avait'::text,'avait l''habitude d''avoir'::text,'Évidemment, cette équipe avait avant zéro unité en cuisine.'::text),
(399689,44410,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki bu ekibin mutfakta hiç birliği ...'::text,'yoktu'::text,'olmazdı'::text,'olmamaya alışkındı'::text,'Tabii ki bu ekibin mutfakta hiç birliği yoktu.'::text),
(399690,44410,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván ennek a csapatnak ... nulla egysége a konyhában.'::text,'régen volt'::text,'volt'::text,'hozzá volt szokva, hogy legyen'::text,'Nyilván ennek a csapatnak régen volt nulla egysége a konyhában.'::text),
(399693,44411,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dieses Team wird die ganze Nacht weiter diesen Einheits-Vibe ...'::text,'zeigen'::text,'zeigen'::text,'zeigen'::text,'Bro, dieses Team wird die ganze Nacht weiter diesen Einheits-Vibe zeigen.'::text),
(399697,44411,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ця команда всю ніч і далі буде ... цей вайб єдності.'::text,'показувати'::text,'показувати'::text,'показувати'::text,'Бро, ця команда всю ніч і далі буде показувати цей вайб єдності.'::text),
(399696,44411,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, este equipo va a seguir ... ese rollo de unidad toda la noche.'::text,'mostrando'::text,'mostrar'::text,'mostrar'::text,'Bro, este equipo va a seguir mostrando ese rollo de unidad toda la noche.'::text),
(399695,44411,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, cette équipe va continuer à ... cette vibe d''unité toute la nuit.'::text,'montrer'::text,'montrer'::text,'montrer'::text,'Frérot, cette équipe va continuer à montrer cette vibe d''unité toute la nuit.'::text),
(399698,44411,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu ekip bütün gece o birlik havasını ... devam edecek.'::text,'göstermeye'::text,'göstermeye'::text,'göstermek'::text,'Kanka, bu ekip bütün gece o birlik havasını göstermeye devam edecek.'::text),
(399699,44411,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez a csapat egész éjjel tovább fogja ... azt az egység-vibe-ot.'::text,'nyomni'::text,'nyomni'::text,'nyomni'::text,'Tesó, ez a csapat egész éjjel tovább fogja nyomni azt az egység-vibe-ot.'::text),
(399702,44412,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die Einheit von dem Team ist schon irgendwie ikonisch, ...?'::text,'oder'::text,'nicht'::text,'ja'::text,'Yo, die Einheit von dem Team ist schon irgendwie ikonisch, oder?'::text),
(399706,44412,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, єдність цієї команди якась культова, ...?'::text,'правда'::text,'чи не так'::text,'так'::text,'Йо, єдність цієї команди якась культова, правда?'::text),
(399705,44412,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, la unidad de ese equipo es bastante icónica, ¿...?'::text,'verdad'::text,'no'::text,'sí'::text,'Oye, la unidad de ese equipo es bastante icónica, ¿verdad?'::text),
(399704,44412,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, l''unité de cette équipe est un peu iconique, ... ?'::text,'non'::text,'hein'::text,'oui'::text,'Wesh, l''unité de cette équipe est un peu iconique, non ?'::text),
(399707,44412,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o ekibin birliği biraz efsane, ...?'::text,'değil mi'::text,'değil mi'::text,'öyle mi'::text,'Kanka, o ekibin birliği biraz efsane, değil mi?'::text),
(399708,44412,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, annak a csapatnak az egysége elég ikonikus, ...?'::text,'nem'::text,'ugye'::text,'igen'::text,'Tesó, annak a csapatnak az egysége elég ikonikus, nem?'::text),
(391350,43484,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wendeltreppe ist nicht sehr breit, und ...'::text,'die Betontreppe auch nicht'::text,'die Betontreppe auch'::text,'die Betontreppe auch nicht'::text,'Die Wendeltreppe ist nicht sehr breit, und die Betontreppe auch nicht.'::text),
(391354,43484,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гвинтові сходи не дуже широкі, і ...'::text,'бетонні теж ні'::text,'бетонні теж'::text,'бетонні теж ні'::text,'Гвинтові сходи не дуже широкі, і бетонні теж ні.'::text),
(391353,43484,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La escalera de caracol no es muy ancha, y ...'::text,'la de hormigón tampoco'::text,'la de hormigón también'::text,'la de hormigón tampoco'::text,'La escalera de caracol no es muy ancha, y la de hormigón tampoco.'::text),
(391352,43484,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''escalier en colimaçon n''est pas très large, et ...'::text,'celui en béton non plus'::text,'celui en béton aussi'::text,'celui en béton non plus'::text,'L''escalier en colimaçon n''est pas très large, et celui en béton non plus.'::text),
(391355,43484,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Döner merdiven çok geniş değil, ...'::text,'beton olan da değil'::text,'beton olan da öyle'::text,'beton olan da değil'::text,'Döner merdiven çok geniş değil, beton olan da değil.'::text),
(391356,43484,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csigalépcső nem túl széles, és ...'::text,'a betonlépcső sem'::text,'a betonlépcső is'::text,'a betonlépcső sem'::text,'A csigalépcső nem túl széles, és a betonlépcső sem.'::text),
(391359,43485,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... eine Stunde lang geklettert, bevor du diese Marmortreppe erreicht hast. Respekt.'::text,'warst'::text,'bist'::text,'warst'::text,'Ehrlich, du warst eine Stunde lang geklettert, bevor du diese Marmortreppe erreicht hast. Respekt.'::text),
(391363,43485,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... цілу годину, перш ніж дістався тих мармурових сходів. Респект.'::text,'підіймався'::text,'підіймаєшся'::text,'підіймався'::text,'Чесно, ти підіймався цілу годину, перш ніж дістався тих мармурових сходів. Респект.'::text),
(391362,43485,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... una hora subiendo antes de llegar a esa escalera de mármol. Respeto.'::text,'llevabas'::text,'llevas'::text,'estabas'::text,'Sinceramente, llevabas una hora subiendo antes de llegar a esa escalera de mármol. Respeto.'::text),
(391361,43485,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... depuis une heure quand tu as atteint cet escalier en marbre. Respect.'::text,'montais'::text,'montes'::text,'montais'::text,'Franchement, tu montais depuis une heure quand tu as atteint cet escalier en marbre. Respect.'::text),
(391364,43485,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bir saattir ... o mermer merdivene varana kadar. Saygı.'::text,'tırmanıyordun'::text,'tırmanıyorsun'::text,'tırmanıyordun'::text,'Açıkçası, bir saattir tırmanıyordun o mermer merdivene varana kadar. Saygı.'::text),
(391365,43485,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, egy órán át ..., mielőtt elérted azt a márványlépcsőt. Respekt.'::text,'másztál'::text,'mászol'::text,'másztál'::text,'Őszintén, egy órán át másztál, mielőtt elérted azt a márványlépcsőt. Respekt.'::text),
(391368,43486,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Tages wird er vier Treppen in vier Gebäuden ...'::text,'bestiegen haben'::text,'besteigen'::text,'besteigen'::text,'Bis zum Ende des Tages wird er vier Treppen in vier Gebäuden bestiegen haben.'::text),
(391372,43486,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця дня він ... сходи в чотирьох різних будівлях.'::text,'подолає'::text,'подолає'::text,'долатиме'::text,'До кінця дня він подолає сходи в чотирьох різних будівлях.'::text),
(391371,43486,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al final del día, ... cuatro escaleras en cuatro edificios.'::text,'habrá subido'::text,'subirá'::text,'estará subiendo'::text,'Al final del día, habrá subido cuatro escaleras en cuatro edificios.'::text),
(391370,43486,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la journée, il ... quatre escaliers dans quatre bâtiments.'::text,'aura monté'::text,'montera'::text,'sera en train de monter'::text,'D''ici la fin de la journée, il aura monté quatre escaliers dans quatre bâtiments.'::text),
(391373,43486,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün sonuna kadar dört binada dört merdiven ...'::text,'tırmanmış olacak'::text,'tırmanacak'::text,'tırmanıyor olacak'::text,'Gün sonuna kadar dört binada dört merdiven tırmanmış olacak.'::text),
(391374,43486,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nap végére ... négy lépcsőt négy épületben.'::text,'megmássza'::text,'meg fogja mászni'::text,'mászni fogja'::text,'A nap végére megmássza négy lépcsőt négy épületben.'::text),
(391377,43487,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um zwölf Uhr ... er seit drei Stunden ohne Pause Treppen.'::text,'steigt'::text,'steigt gerade'::text,'ist gestiegen'::text,'Um zwölf Uhr steigt er seit drei Stunden ohne Pause Treppen.'::text),
(391381,43487,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду він ... сходами вже три години без перерви.'::text,'підійматиметься'::text,'підійматиметься'::text,'піднімався'::text,'До обіду він підійматиметься сходами вже три години без перерви.'::text),
(391380,43487,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mediodía, ... tres horas subiendo escaleras sin descanso.'::text,'llevará'::text,'estará'::text,'ha estado'::text,'A mediodía, llevará tres horas subiendo escaleras sin descanso.'::text),
(391379,43487,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À midi, cela ... trois heures qu''il monte des escaliers sans pause.'::text,'fera'::text,'fera'::text,'a fait'::text,'À midi, cela fera trois heures qu''il monte des escaliers sans pause.'::text),
(391382,43487,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar üç saattir aralıksız merdiven ...'::text,'tırmanıyor olacak'::text,'tırmanıyor olacak'::text,'tırmandı'::text,'Öğlene kadar üç saattir aralıksız merdiven tırmanıyor olacak.'::text),
(391383,43487,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre már három órája ... lépcsőt szünet nélkül.'::text,'mászik majd'::text,'mászik majd'::text,'mászott'::text,'Délre már három órája mászik majd lépcsőt szünet nélkül.'::text),
(391386,43488,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er nicht die Treppe genommen hätte, ... er die prächtige Marmortreppe nicht gefunden.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn er nicht die Treppe genommen hätte, hätte er die prächtige Marmortreppe nicht gefunden.'::text),
(391390,43488,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не пішов сходами, то ... величних мармурових сходів.'::text,'не знайшов би'::text,'не знайде'::text,'не знайшов'::text,'Якби він не пішов сходами, то не знайшов би величних мармурових сходів.'::text),
(391389,43488,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera subido por las escaleras, ... la gran escalera de mármol.'::text,'no habría encontrado'::text,'no encontrará'::text,'no encontró'::text,'Si no hubiera subido por las escaleras, no habría encontrado la gran escalera de mármol.'::text),
(391388,43488,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas pris l''escalier, il ... le grand escalier en marbre.'::text,'n''aurait pas trouvé'::text,'ne trouvera pas'::text,'n''a pas trouvé'::text,'S''il n''avait pas pris l''escalier, il n''aurait pas trouvé le grand escalier en marbre.'::text),
(391391,43488,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Merdivenleri kullanmasaydı o görkemli mermer merdiveni ...'::text,'bulamazdı'::text,'bulamayacak'::text,'bulamadı'::text,'Merdivenleri kullanmasaydı o görkemli mermer merdiveni bulamazdı.'::text),
(391392,43488,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem a lépcsőt választotta volna, ... a pompás márványlépcsőt.'::text,'nem találta volna meg'::text,'nem fogja megtalálni'::text,'nem találta meg'::text,'Ha nem a lépcsőt választotta volna, nem találta volna meg a pompás márványlépcsőt.'::text),
(391395,43489,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er den Aufzug genommen hätte, ... er jetzt nicht so begeistert von der Treppe.'::text,'wäre'::text,'wäre'::text,'wird'::text,'Wenn er den Aufzug genommen hätte, wäre er jetzt nicht so begeistert von der Treppe.'::text),
(391399,43489,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він поїхав ліфтом, то зараз ... так вражений сходами.'::text,'не був би'::text,'не був би'::text,'не буде'::text,'Якби він поїхав ліфтом, то зараз не був би так вражений сходами.'::text),
(391398,43489,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera cogido el ascensor, ahora ... tan asombrado con la escalera.'::text,'no estaría'::text,'no habría estado'::text,'no estará'::text,'Si hubiera cogido el ascensor, ahora no estaría tan asombrado con la escalera.'::text),
(391397,43489,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait pris l''ascenseur, il ... aussi impressionné par l''escalier maintenant.'::text,'ne serait pas'::text,'n''aurait pas été'::text,'ne sera pas'::text,'S''il avait pris l''ascenseur, il ne serait pas aussi impressionné par l''escalier maintenant.'::text),
(391400,43489,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Asansörü kullansaydı şimdi merdivene bu kadar hayran ...'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'Asansörü kullansaydı şimdi merdivene bu kadar hayran olmazdı.'::text),
(391401,43489,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha liftet használt volna, most ... ennyire lenyűgözve a lépcsőtől.'::text,'nem lenne'::text,'nem lett volna'::text,'nem lesz'::text,'Ha liftet használt volna, most nem lenne ennyire lenyűgözve a lépcsőtől.'::text),
(391404,43490,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Marmortreppe soll vor über hundert Jahren ...'::text,'gebaut worden sein'::text,'bauen'::text,'gebaut werdend'::text,'Die Marmortreppe soll vor über hundert Jahren gebaut worden sein.'::text),
(391408,43490,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що мармурові сходи ... понад сто років тому.'::text,'збудували'::text,'будувати'::text,'будуючи'::text,'Кажуть, що мармурові сходи збудували понад сто років тому.'::text),
(391407,43490,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que la escalera de mármol ... hace más de cien años.'::text,'fue construida'::text,'construir'::text,'siendo construida'::text,'Se dice que la escalera de mármol fue construida hace más de cien años.'::text),
(391406,43490,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que l''escalier en marbre ... il y a plus de cent ans.'::text,'a été construit'::text,'construire'::text,'étant construit'::text,'On dit que l''escalier en marbre a été construit il y a plus de cent ans.'::text),
(391409,43490,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mermer merdivenin yüz yıldan uzun süre önce ... söyleniyor.'::text,'yapılmış olduğu'::text,'yapmak'::text,'yapılırken'::text,'Mermer merdivenin yüz yıldan uzun süre önce yapılmış olduğu söyleniyor.'::text),
(391410,43490,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, hogy a márványlépcső több mint száz éve ...'::text,'épült'::text,'építeni'::text,'épülve'::text,'Azt mondják, hogy a márványlépcső több mint száz éve épült.'::text),
(391413,43491,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bro hat abgestritten, nach der vierten Treppe müde ..., ohne Witz.'::text,'gewesen zu sein'::text,'zu sein'::text,'sein'::text,'Der Bro hat abgestritten, nach der vierten Treppe müde gewesen zu sein, ohne Witz.'::text),
(391417,43491,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро заперечував, що ... втомленим після четвертих сходів, без брехні.'::text,'був'::text,'бути'::text,'бути'::text,'Бро заперечував, що був втомленим після четвертих сходів, без брехні.'::text),
(391416,43491,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El bro negó ... cansado después de la cuarta escalera, en serio.'::text,'estar'::text,'estar'::text,'estar'::text,'El bro negó estar cansado después de la cuarta escalera, en serio.'::text),
(391415,43491,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le frérot a nié ... fatigué après le quatrième escalier, sans mentir.'::text,'être'::text,'être'::text,'être'::text,'Le frérot a nié être fatigué après le quatrième escalier, sans mentir.'::text),
(391418,43491,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka dördüncü merdivenden sonra yorgun ... inkâr etti, yemin ederim.'::text,'olduğunu'::text,'olmayı'::text,'olmak'::text,'Kanka dördüncü merdivenden sonra yorgun olduğunu inkâr etti, yemin ederim.'::text),
(391419,43491,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tesó tagadta, hogy fáradt ... a negyedik lépcső után, komolyan.'::text,'lett volna'::text,'lenni'::text,'lenni'::text,'A tesó tagadta, hogy fáradt lett volna a negyedik lépcső után, komolyan.'::text),
(391422,43492,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, nach vier Treppen ... er so müde gewesen sein, ohne Witz.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Bro, nach vier Treppen muss er so müde gewesen sein, ohne Witz.'::text),
(391426,43492,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, після чотирьох сходів він ... таким утомленим, без брехні.'::text,'напевно був'::text,'мав бути'::text,'не може бути'::text,'Бро, після чотирьох сходів він напевно був таким утомленим, без брехні.'::text),
(391425,43492,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, después de cuatro escaleras ... estar muy cansado, en serio.'::text,'debió de'::text,'debió'::text,'no puede'::text,'Bro, después de cuatro escaleras debió de estar muy cansado, en serio.'::text),
(391424,43492,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, après quatre escaliers, il ... être super fatigué, sans mentir.'::text,'a dû'::text,'aurait dû'::text,'ne peut pas'::text,'Frérot, après quatre escaliers, il a dû être super fatigué, sans mentir.'::text),
(391427,43492,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dört merdivenden sonra çok yorulmuş ..., yemin ederim.'::text,'olmalı'::text,'olmalıydı'::text,'olamaz'::text,'Kanka, dört merdivenden sonra çok yorulmuş olmalı, yemin ederim.'::text),
(391428,43492,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, négy lépcső után nagyon fáradtnak ... lennie, komolyan.'::text,'kellett'::text,'kellett volna'::text,'nem lehet'::text,'Tesó, négy lépcső után nagyon fáradtnak kellett lennie, komolyan.'::text),
(391431,43493,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... eine Treppe mit einem Budget von 2 Millionen Euro bestiegen.'::text,'hat er'::text,'er hat'::text,'er'::text,'Selten hat er eine Treppe mit einem Budget von 2 Millionen Euro bestiegen.'::text),
(391435,43493,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Нечасто ... сходами з бюджетом у 2 мільйони євро.'::text,'підіймався він'::text,'він підіймався'::text,'він піднявся'::text,'Нечасто підіймався він сходами з бюджетом у 2 мільйони євро.'::text),
(391434,43493,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pocas veces ... una escalera con un presupuesto de 2 millones de euros.'::text,'ha subido él'::text,'él ha subido'::text,'él subió'::text,'Pocas veces ha subido él una escalera con un presupuesto de 2 millones de euros.'::text),
(391433,43493,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... un escalier avec un budget de 2 millions d''euros.'::text,'a-t-il monté'::text,'il a monté'::text,'il monta'::text,'Rarement a-t-il monté un escalier avec un budget de 2 millions d''euros.'::text),
(391436,43493,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadiren 2 milyon avro bütçeli bir merdiven ...'::text,'tırmandı'::text,'tırmandı'::text,'tırmanmıştı'::text,'Nadiren 2 milyon avro bütçeli bir merdiven tırmandı.'::text),
(391437,43493,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... 2 millió eurós költségvetésű lépcsőn.'::text,'mászott fel'::text,'ő mászott fel'::text,'mászott'::text,'Ritkán mászott fel 2 millió eurós költségvetésű lépcsőn.'::text),
(380307,42257,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während die Menge den Moment in Stille ..., wäre fast eine Fahne umgefallen!'::text,'würdigte'::text,'würdigte'::text,'gewürdigt hat'::text,'Während die Menge den Moment in Stille würdigte, wäre fast eine Fahne umgefallen!'::text),
(380311,42257,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки натовп мовчки ... ту мить, один прапор мало не впав!'::text,'вшановував'::text,'вшанував'::text,'вшанував'::text,'Поки натовп мовчки вшановував ту мить, один прапор мало не впав!'::text),
(380310,42257,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mientras el público ... el momento en silencio, una bandera casi se cae!'::text,'respetaba'::text,'respetó'::text,'ha respetado'::text,'¡Mientras el público respetaba el momento en silencio, una bandera casi se cae!'::text),
(380309,42257,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que la foule ... ce moment en silence, un drapeau a failli tomber !'::text,'respectait'::text,'respecta'::text,'a respecté'::text,'Pendant que la foule respectait ce moment en silence, un drapeau a failli tomber !'::text),
(380312,42257,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık o anı sessizce ..., bir bayrak neredeyse devriliyordu!'::text,'saygıyla anarken'::text,'saygıyla andı'::text,'saygıyla anmış'::text,'Kalabalık o anı sessizce saygıyla anarken, bir bayrak neredeyse devriliyordu!'::text),
(380313,42257,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a tömeg csendben ... a pillanatot, egy zászló majdnem összedőlt!'::text,'tisztelte'::text,'megtisztelte'::text,'megtisztelte már'::text,'Miközben a tömeg csendben tisztelte a pillanatot, egy zászló majdnem összedőlt!'::text),
(380325,42259,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann stand auf und ... den Moment mit der Hand auf der Brust.'::text,'würdigte'::text,'würdigte gerade'::text,'würdigt'::text,'Der Mann stand auf und würdigte den Moment mit der Hand auf der Brust.'::text),
(380329,42259,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік підвівся і ... ту мить із рукою на грудях.'::text,'вшанував'::text,'вшановував'::text,'вшановує'::text,'Чоловік підвівся і вшанував ту мить із рукою на грудях.'::text),
(380328,42259,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre se levantó y ... el momento con la mano en el pecho.'::text,'respetó'::text,'estaba respetando'::text,'respeta'::text,'El hombre se levantó y respetó el momento con la mano en el pecho.'::text),
(380327,42259,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme s''est levé et ... le moment la main sur le cœur.'::text,'a respecté'::text,'respectait'::text,'respecte'::text,'L''homme s''est levé et a respecté le moment la main sur le cœur.'::text),
(380330,42259,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam ayağa kalktı ve eli göğsünde o anı saygıyla ...'::text,'andı'::text,'anıyordu'::text,'anıyor'::text,'Adam ayağa kalktı ve eli göğsünde o anı saygıyla andı.'::text),
(380331,42259,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi felállt, és kezét a mellkasán tartva ... a pillanatot.'::text,'megtisztelte'::text,'tisztelte'::text,'tiszteli'::text,'A férfi felállt, és kezét a mellkasán tartva megtisztelte a pillanatot.'::text),
(380334,42260,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Menge ... die Schweigeminute eingehalten, und jetzt kann das Spiel beginnen.'::text,'hat'::text,'hat'::text,'hält'::text,'Die Menge hat die Schweigeminute eingehalten, und jetzt kann das Spiel beginnen.'::text),
(380338,42260,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Натовп ... хвилину мовчання, і тепер матч може починатися.'::text,'вшанував'::text,'вшановує'::text,'вшановує'::text,'Натовп вшанував хвилину мовчання, і тепер матч може починатися.'::text),
(380337,42260,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El público ... el minuto de silencio, y ahora el partido puede empezar.'::text,'ha respetado'::text,'ha estado respetando'::text,'respeta'::text,'El público ha respetado el minuto de silencio, y ahora el partido puede empezar.'::text),
(380336,42260,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La foule ... la minute de silence, et maintenant le match peut commencer.'::text,'a respecté'::text,'respecte depuis un moment'::text,'respecte'::text,'La foule a respecté la minute de silence, et maintenant le match peut commencer.'::text),
(380339,42260,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık saygı duruşuna ..., şimdi maç başlayabilir.'::text,'uydu'::text,'uyuyor'::text,'uyar'::text,'Kalabalık saygı duruşuna uydu, şimdi maç başlayabilir.'::text),
(380340,42260,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tömeg ... a néma percet, és most kezdődhet a meccs.'::text,'megtartotta'::text,'tartja'::text,'tartja'::text,'A tömeg megtartotta a néma percet, és most kezdődhet a meccs.'::text),
(380343,42261,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz klar ein kleiner Wunsch: Die Fans wünschten, die Gästefans ... letzte Saison die Stille respektiert.'::text,'hätten'::text,'haben'::text,'würden'::text,'Ganz klar ein kleiner Wunsch: Die Fans wünschten, die Gästefans hätten letzte Saison die Stille respektiert.'::text),
(380347,42261,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно скромне бажання: фанати хотіли б, щоб гостьові вболівальники минулого сезону ... тишу.'::text,'поважали б'::text,'поважали'::text,'поважали б'::text,'Явно скромне бажання: фанати хотіли б, щоб гостьові вболівальники минулого сезону поважали б тишу.'::text),
