(380345,42261,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un petit souhait : les fans aimeraient que les supporters adverses ... le silence la saison dernière.'::text,'aient respecté'::text,'respectaient'::text,'respecteraient'::text,'Clairement un petit souhait : les fans aimeraient que les supporters adverses aient respecté le silence la saison dernière.'::text),
(380348,42261,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki küçük bir dilek: taraftarlar keşke deplasman taraftarları geçen sezon sessizliğe ... diyor.'::text,'saygı gösterseydi'::text,'saygı gösterdi'::text,'saygı gösterse'::text,'Belli ki küçük bir dilek: taraftarlar keşke deplasman taraftarları geçen sezon sessizliğe saygı gösterseydi diyor.'::text),
(380349,42261,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván apró kívánság: a szurkolók azt szeretnék, bárcsak a vendégszurkolók a múlt szezonban ... a csendet.'::text,'tiszteletben tartották volna'::text,'tiszteletben tartották'::text,'tiszteletben tartanák'::text,'Nyilván apró kívánság: a szurkolók azt szeretnék, bárcsak a vendégszurkolók a múlt szezonban tiszteletben tartották volna a csendet.'::text),
(380352,42262,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der große Typ, ... Hand auf der Brust liegt, respektiert den Moment echt.'::text,'dessen'::text,'der'::text,'was'::text,'Bro, der große Typ, dessen Hand auf der Brust liegt, respektiert den Moment echt.'::text),
(380356,42262,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, той здоровань, ... рука на грудях, реально поважає цю мить.'::text,'чия'::text,'який'::text,'що'::text,'Бро, той здоровань, чия рука на грудях, реально поважає цю мить.'::text),
(380355,42262,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el grandullón, ... mano está en el pecho, respeta el momento de verdad.'::text,'cuya'::text,'que'::text,'el cual'::text,'Bro, el grandullón, cuya mano está en el pecho, respeta el momento de verdad.'::text),
(380354,42262,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le grand gars, ... la main est sur la poitrine, respecte vraiment le moment.'::text,'dont'::text,'qui'::text,'que'::text,'Frérot, le grand gars, dont la main est sur la poitrine, respecte vraiment le moment.'::text),
(380357,42262,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eli göğsünde olan o iri adam ... o ana cidden saygı gösteriyor.'::text,''::text,NULL::text,NULL::text,'Kanka, eli göğsünde olan o iri adam o ana cidden saygı gösteriyor.'::text),
