(380385,42265,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tömeg 1990 óta minden szezonban ... a néma percet.'::text,'megtartja'::text,'megtartja'::text,'éppen megtartja'::text,'A tömeg 1990 óta minden szezonban megtartja a néma percet.'::text),
(380397,42267,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Menge wird ihren Verein für immer ..., sogar nach der schlimmsten Niederlage!'::text,'respektieren'::text,'respektiert haben'::text,'respektiert'::text,'Diese Menge wird ihren Verein für immer respektieren, sogar nach der schlimmsten Niederlage!'::text),
